var gununBilgisiData = [{"tip":"ayet","metin":"Ey sevgili Peygamberim “sallallahü aleyhi ve sellem”! Seni, dünyâdaki bütün insanlara ebedî se’âdeti müjdelemek ve bu se’âdet yolunu göstermek için, beşeriyyete gönderiyorum","kisim":1,"madde":1},{"tip":"hadis","metin":"Allahü teâlâ, sizin sûretlerinize, mallarınıza, bakmaz. Kalblerinize ve amellerinize bakar","kisim":1,"madde":1},{"tip":"hadis","metin":"Bir sâat ilm öğrenmek veyâ öğretmek, sabâha kadar ibâdet etmekden dahâ sevâbdır","kisim":1,"madde":1},{"tip":"hadis","metin":"Kur’ân-ı kerîmden kendi aklı ile, kendi düşüncesi ve bilgisi ile ma’nâ çıkaran kâfirdir","kisim":1,"madde":8},{"tip":"ayet","metin":"Bu düşmanların düâları netîcesizdir. Kabûl olmak ihtimâli yokdur","kisim":1,"madde":11},{"tip":"hadis","metin":"Müslimânlar, âhırete inanıyor. Kitâbsız kâfirler, inkâr ediyor. Tekrâr dirilmek olmasaydı, inanmıyanlar birşey kazanmaz, müslimânlar da, zarar etmezdi. Fekat, kâfirlerin dediği olmayınca, sonsuz azâb çekeceklerdir","kisim":1,"madde":11},{"tip":"hadis","metin":"Oğullarınıza yüzmek ve ok atmak öğretiniz! Kadınların, evinde iplik iğirmesi ne güzel eğlencedir","kisim":1,"madde":11},{"tip":"ayet","metin":"Allahü teâlâ, kullarına zulm etmez, haksızlık etmez. Onlar, kendilerini azâba, acılara sürükleyen bozuk düşünceleri, çirkin işleri ile kendilerine zulm ve işkence ediyorlar","kisim":1,"madde":12},{"tip":"ayet","metin":"Kâfirler, mal ve çok evlâd gibi dünyâlıkları verdiğimiz için, kendilerine iyilik mi ediyoruz, yardım mı ediyoruz sanıyor. Peygamberime “sallallahü aleyhi ve sellem” inanmadıkları ve dîn-i islâmı beğenmedikleri için, onlara mükâfât mı ediyoruz, diyorlar? Hayır öyle değildir. Aldanıyorlar. Bunların ni’met olmayıp, musîbet olduğunu anlamıyorlar","kisim":1,"madde":13},{"tip":"hadis","metin":"Çok müslimân evlâdı, babaları yüzünden Veyl ismindeki Cehenneme gideceklerdir. Çünki, bunların babaları, yalnız para kazanmak ve keyf sürmek hırsına düşüp ve yalnız dünyâ işleri arkasında koşup, evlâdlarına müslimânlığı ve Kur’ân-ı kerîmi öğretmediler. Ben böyle babalardan uzağım. Onlar da, benden uzakdır. Çocuklarına dinlerini öğretmiyenler, Cehenneme gideceklerdir","kisim":1,"madde":18},{"tip":"hadis","metin":"Çocuklarına Kur’ân-ı kerîm öğretenlere veyâ Kur’ân-ı kerîm hocasına gönderenlere, öğretilen Kur’ânın her harfi için, on kerre Kâ’be-i mu’azzama ziyâreti sevâbı verilir ve kıyâmet günü, başına devlet tâcı konur. Bütün insanlar görüp imrenir","kisim":1,"madde":18},{"tip":"hadis","metin":"Çocuklarınıza nemâz kılmasını öğretiniz. Yedi yaşına gelince, nemâzı emr ediniz. On yaşına gelince kılmazlar ise, döverek kıldırınız","kisim":1,"madde":18},{"tip":"hadis","metin":"Bir müslimânın evlâdı ibâdet edince, kazandığı sevâb kadar, babasına da verilir. Bir kimse, çocuğuna fısk, günâh öğretirse, bu çocuk ne kadar günâh işlerse, babasına da o kadar günâh yazılır","kisim":1,"madde":18},{"tip":"hadis","metin":"Bütün ibâdetlere verilen sevâb, Allah yolunda gazâya verilen sevâba göre, deniz yanında bir damla su gibidir. Gazânın sevâbı da, emr-i ma’rûf ve nehy-i anilmünker sevâbı yanında, denize nazaran bir damla su gibidir","kisim":1,"madde":18},{"tip":"hadis","metin":"Zevcesinin ve çocuklarının haklarını îfâ etmiyenin nemâzları, orucları kabûl olmaz","kisim":1,"madde":18},{"tip":"ayet","metin":"Allahü teâlâya ve kıyâmet gününe îmân edenler, Allahü teâlânın ve resûlünün düşmanlarını sevmezler. O kâfirler ve münâfıklar, mü’minlerin anaları, babaları, oğulları, kardeşleri ve başka yakınları olsa da, bunları sevmezler. Böyle olan mü’minleri Cennete koyacağım","kisim":1,"madde":19},{"tip":"hadis","metin":"Îmânın temeli ve en kuvvetli alâmeti, müslimânları sevmek ve müslimânlara düşmanlık edenleri sevmemekdir","kisim":1,"madde":19},{"tip":"ayet","metin":"Kâfirlerin hücûm ve işkencelerine uğramamak, onları da, se’âdet-i ebediyyeye kavuşdurmak için, insan gücünün yetdiği kadar durmadan çalışınız. En mükemmel harb vâsıtalarını yapınız!","kisim":1,"madde":20},{"tip":"ayet","metin":"Kâfirlerin câmi’ yapmaları câiz değildir. Yerinde ve yarar bir iş değildir. Onların câmi’ yapmaları ve diğer bütün beğendikleri işleri, kıyâmetde kendilerine yaramıyacak ve Muhammed aleyhisselâma tâbi’ olmadıkları için, Cehenneme girip, çok acı azâblarda sonsuz olarak cezâlandırılacaklardır","kisim":1,"madde":21},{"tip":"ayet","metin":"Muhammed aleyhisselâmın getirdiği İslâm dîninden başka din istiyenlerin, dinlerini Allahü teâlâ sevmez ve kabûl etmez. Dîn-i islâma arka çeviren, âhıretde ziyân edecek, Cehenneme girecekdir","kisim":1,"madde":21},{"tip":"ayet","metin":"Allahü teâlânın ve Peygamberi Muhammed aleyhisselâmın emrlerine aldırış etmiyenler, beğenmiyenler, asra, fenne uygun değildir, modern ihtiyâclara kâfi değildir diyenler, kıyâmetde Cehennem ateşinden kurtulamıyacaklardır. Bunlara, Cehennemde, çok acı azâb vardır","kisim":1,"madde":21},{"tip":"hadis","metin":"O kimse yine mü’mindir. Günâh işlemekle, îmânı gitmez","kisim":1,"madde":31},{"tip":"hadis","metin":"Kardeşlerimiz bizden ayrıldı. Onlar kâfir, fâsık değildir. Çünki, ictihâdlarına göre hareket ediyorlar","kisim":1,"madde":31},{"tip":"hadis","metin":"Eshâbıma dil uzatmakdan sakınınız!","kisim":1,"madde":31},{"tip":"ayet","metin":"Allahü teâlâ, size kolay olan şeyleri yapdırmak istiyor, güç olanı istemiyor","kisim":1,"madde":35},{"tip":"ayet","metin":"Allahü teâlâ, ibâdetlerinizin hafîf, kolay olmasını istiyor. İnsan za’îf, dayanıksız yaratıldı","kisim":1,"madde":35},{"tip":"hadis","metin":"Öyle ise, şimdiden onlara cevâb hâzırla!","kisim":1,"madde":36},{"tip":"ayet","metin":"Rabbinin rızâsına kavuşmak istiyen için, bu elbette bir nasîhatdir","kisim":1,"madde":37},{"tip":"ayet","metin":"Rabbiniz Erdı sizin için, yatak gibi döşedi","kisim":1,"madde":39},{"tip":"ayet","metin":"Erdın sizi sarsmaması için, üzerinde dağlar döşedim","kisim":1,"madde":39},{"tip":"ayet","metin":"Zulm edenlere ve etmiyenlere birlikde gelen fitne ve belâdan korkunuz, sakınınız","kisim":1,"madde":41},{"tip":"hadis","metin":"Sôfiyye arasında emr-i ma’rûfa ve nehy-i münkere nikâr denir","kisim":1,"madde":41},{"tip":"hadis","metin":"Kalbe gelen bütün keşfleri, hâlleri bize verseler, fekat kalbimizi Ehl-i sünnet i’tikâdı ile süslemeseler, kendimi mahv olmuş ve hâlimi harâb bilirim. Bütün harâblıkları, felâketleri üzerime yığsalar, lâkin kalbimi Ehl-i sünnet vel-cemâ’at i’tikâdı ile şereflendirseler, hiç üzülmem","kisim":1,"madde":41},{"tip":"hadis","metin":"Îmânında veyâ ibâdetinde bid’at, bozukluk bulunan bir kimseye, Allah için sert bakanın kalbini, Allahü teâlâ îmânla doldurur ve korkudan korur","kisim":1,"madde":41},{"tip":"hadis","metin":"Günâh işleyeni, eliniz ile men’ ediniz, buna kuvvetiniz yetmezse, söz ile mâni’ olunuz. Bunu da yapamaz iseniz, kalbiniz ile beğenmeyiniz! Bu ise, îmânın en aşağısıdır","kisim":1,"madde":41},{"tip":"hadis","metin":"Allahü teâlâ, Cebrâîl aleyhisselâma, filân şehri yerin dibine geçir, diye emr etdi. Cebrâîl, yâ Rabbî! Bu şehrdeki filânca kulun sana bir ân ısyân etmedi. Hep itâ’at ve ibâdet ediyor deyince, onu da berâber geçir! Zîrâ günâh işleyenleri görünce, bir kerrecik yüzünü değişdirmedi","kisim":1,"madde":41},{"tip":"hadis","metin":"Dîninizin direği, temeli vera’dır","kisim":1,"madde":42},{"tip":"ayet","metin":"Ey mü’minler! Hepiniz, Allahü teâlâya tevbe ediniz! Tevbe etmekle kurtulabilirsiniz","kisim":1,"madde":43},{"tip":"ayet","metin":"Ey îmân eden seçilmişler! Allahü teâlâya dönünüz! Hâlis tevbe edin! Ya’nî tevbenizi bozmayın! Böyle tevbe edince, Rabbiniz, sizi belki afv eder ve ağaçlarının, köşklerinin altından [önünden] sular akan Cennetlere sokar","kisim":1,"madde":43},{"tip":"ayet","metin":"Açık olsun, gizli olsun günâhlardan sakınınız!","kisim":1,"madde":43},{"tip":"hadis","metin":"Harâm olarak ele geçen bir kuruşu, sâhibine geri vermek, yüz kuruş sadaka vermekden dahâ sevâbdır","kisim":1,"madde":43},{"tip":"hadis","metin":"Allahü teâlâ buyuruyor ki: Ey kulum! Emr etdiğim farzları yap, insanların en âbidi olursun. Yasak etdiğim harâmlardan sakın, vera’ sâhibi olursun. Verdiğim rızka kanâ’at eyle, insanların en ganîsi olursun, kimseye muhtâc kalmazsın","kisim":1,"madde":43},{"tip":"hadis","metin":"Vera’ sâhibi ol ki, insanların en âbidi olursun!","kisim":1,"madde":43},{"tip":"hadis","metin":"Kıyâmet günü Allahü teâlânın huzûrunda kıymetli olanlar vera’ ve zühd sâhibleridir","kisim":1,"madde":43},{"tip":"hadis","metin":"Bir kimse, bir günâh işler, sonra pişmân olursa, bu pişmânlığı, günâhına keffâret olur. Ya’nî, afvına sebeb olur","kisim":1,"madde":43},{"tip":"hadis","metin":"Günâhı olan kimse, istigfâr eder ve tevbe eder, sonra bu günâhı tekrâr yapar, sonra yine istigfâr söyler, tevbe eder. Üçüncüye yine yapar ve yine tevbe ederse, dördüncü olarak yapınca, büyük günâh yazılır","kisim":1,"madde":43},{"tip":"hadis","metin":"Bir nemâzı özrsüz, vaktinden sonra kılan, seksen hukbe Cehennemde yanacakdır. Bir hukbe seksen senedir. Her senesi üçyüzaltmış gündür. Her günü, seksen dünyâ senesidir","kisim":1,"madde":43},{"tip":"ayet","metin":"Mallarını, canlarını fedâ ederek din düşmanları ile, Allah rızâsı için cihâd eden müslimânlar, oturup, ibâdet edenlerden dahâ üstündür. Hepsine de, Cenneti söz veriyorum","kisim":1,"madde":46},{"tip":"ayet","metin":"Resûlümün “sallallahü aleyhi ve sellem” getirdiklerini alınız!","kisim":1,"madde":46},{"tip":"ayet","metin":"Ey îmân edenler, kendinizi ve çoluk çocuğunuzu öyle bir ateşden koruyun ki, onun tutuşdurucusu insanlarla taşlardır","kisim":1,"madde":46},{"tip":"ayet","metin":"Her nemâzı kılarken süslü, temiz, sevilen elbiselerinizi giyiniz!","kisim":1,"madde":46},{"tip":"hadis","metin":"Farz nemâzlarından sonra Âyet-el-kürsî okuyan kimse ile Cennet arasında, ölümden başka mâni’ yokdur","kisim":1,"madde":46},{"tip":"hadis","metin":"Bu düâyı gündüz okuyan, o günün şükrünü yapmış olur. Gece okuyunca, o gecenin şükrünü îfâ etmiş olur","kisim":1,"madde":46},{"tip":"hadis","metin":"Oruc, mü’mini Cehennemden koruyan bir kalkandır","kisim":1,"madde":46},{"tip":"hadis","metin":"Onları seven, beni sevdiği için sever","kisim":1,"madde":46},{"tip":"hadis","metin":"Onlara düşmanlık eden, bana düşman olduğu için eder","kisim":1,"madde":46},{"tip":"hadis","metin":"Kabûl olan bir hac, geçmiş günâhları yok eder","kisim":1,"madde":46},{"tip":"hadis","metin":"Herşeyin menba’ı vardır. İhlâsın, takvânın menba’ı, kaynağı, Âriflerin kalbleridir","kisim":1,"madde":46},{"tip":"hadis","metin":"Kıyâmetde, sahîfesinde çok istigfâr bulunanlara, müjdeler olsun!","kisim":1,"madde":46},{"tip":"ayet","metin":"Sonra, yedi gökü de iki günde var eyledi","kisim":1,"madde":48},{"tip":"hadis","metin":"Ey Eshâbım! Siz öyle bir zemânda geldiniz ki, Allahü teâlânın emrlerinden onda dokuzunu yapıp, birini yapmazsanız, helâk olursunuz, Cehenneme gidersiniz! Bir zemân gelecek ki, o zemânın mü’minleri, emrlerin birini yapabilip, dokuzunu bıraksalar, Cehennemden kurtulurlar. O zemânda îmânı olanlara müjdeler olsun!","kisim":1,"madde":48},{"tip":"ayet","metin":"Sûra bir kerre üfürülünce, yeryüzü ve dağlar, yerlerinden kaldırılıp silkilecekdir. O gün kıyâmet kopacak, gök yarılacak ve dağılacakdır","kisim":1,"madde":49},{"tip":"ayet","metin":"Güneşin karardığı, yıldızların yerlerinden ayrılıp döküldükleri ve dağların dağılıp saçıldıkları zemâna...","kisim":1,"madde":49},{"tip":"ayet","metin":"Gökün yarıldığı ve yıldızların dağılıp yok oldukları zemân...","kisim":1,"madde":49},{"tip":"ayet","metin":"Herşey yok olacakdır. Yalnız O kalacakdır!","kisim":1,"madde":49},{"tip":"ayet","metin":"Ni’metlerime şükr ederseniz, onları artdırırım","kisim":1,"madde":50},{"tip":"hadis","metin":"Her yüz senede bir müceddid zâhir olur. Ümmetimin işlerini yeniler","kisim":1,"madde":50},{"tip":"hadis","metin":"Kirlenince, çabuk gusl abdesti alın! Çünki kirâmen kâtibîn melekleri, cünüb gezen kimseden incinir","kisim":1,"madde":54},{"tip":"hadis","metin":"Resim, köpek ve cünüb kimse bulunan eve rahmet melekleri girmez","kisim":1,"madde":54},{"tip":"hadis","metin":"Misvâk kullanarak kılınan nemâz, misvâksız nemâzdan yetmiş kat üstündür","kisim":1,"madde":54},{"tip":"ayet","metin":"Ey Resûlüm “sallallahü aleyhi ve sellem”! Mü’minlere söyle, harâma bakmasınlar ve avret yerlerini harâmdan korusunlar! Îmânı olan kadınlara da söyle, harâma bakmasınlar ve avret yerlerini harâm işlemekden korusunlar!","kisim":1,"madde":58},{"tip":"hadis","metin":"Allah için yapılan cihâdda düşmanı gözleyen veyâ Allah korkusundan ağlıyan veyâ harâmlara bakmıyan gözler, kıyâmetde Cehennem ateşini görmiyeceklerdir","kisim":1,"madde":58},{"tip":"hadis","metin":"Ananın ayağını öpmek, Cennet kapısının eşiğini öpmek gibidir","kisim":1,"madde":58},{"tip":"hadis","metin":"Nemâz vaktlerinin bir evveli vardır. Bir de sonu vardır","kisim":1,"madde":60},{"tip":"hadis","metin":"İbâdetlerin en kıymetlisi, evvel vaktinde kılınan nemâzdır","kisim":1,"madde":60},{"tip":"hadis","metin":"Bir zemân gelecek, âmirler, imâmlar, nemâzı öldürecekler, vaktinden sonraya bırakacaklardır. Sen, nemâzını vaktinde kıl! Senden sonra, cemâ’at olurlarsa, onlarla da, tekrâr kıl! İkinci kıldığın nâfile olur","kisim":1,"madde":60},{"tip":"hadis","metin":"Mü’min ile kâfiri ayıran fark, nemâzdır","kisim":1,"madde":63},{"tip":"hadis","metin":"Allahü teâlâ, hergün beş vakt nemâz kılmağı farz etdi. Kıymet vererek ve şartlarına uyarak, hergün beş vakt nemâz kılanı Cennete sokacağını, Allahü teâlâ söz verdi","kisim":1,"madde":63},{"tip":"hadis","metin":"Nemâz kılmıyanın, islâmdan nasîbi yokdur!","kisim":1,"madde":63},{"tip":"hadis","metin":"Unutulmuş bir sünnetimi meydâna çıkarana yüz şehîd sevâbı vardır","kisim":1,"madde":64},{"tip":"hadis","metin":"Her nemâzdan sonra, üç kerre, Estagfirullahel’azîm ellezî lâ ilâhe illâ huv el-hayyel-kayyûme ve etûbü ileyh okuyanın, bütün günâhları afv olur","kisim":1,"madde":64},{"tip":"hadis","metin":"Beş vakt farz nemâzdan sonra yapılan düâ kabûl olur","kisim":1,"madde":64},{"tip":"hadis","metin":"Gece seher vaktinde ve nemâzlardan sonra yapılan düâ kabûl olunur","kisim":1,"madde":64},{"tip":"hadis","metin":"Yehûdîlere benzememek için nemâzları, na’lın ile kılınız","kisim":1,"madde":68},{"tip":"hadis","metin":"Elinize geçen resmleri yırtınız, bozunuz!","kisim":1,"madde":68},{"tip":"hadis","metin":"Davulu ve mizmârı yok etmek için emr olundum","kisim":1,"madde":69},{"tip":"hadis","metin":"Müttekî bir âlim ile nemâz kılan, bir Peygamber ile kılmış gibidir","kisim":1,"madde":70},{"tip":"hadis","metin":"Bir müslimân, Cum’a günü gusl abdesti alıp, Cum’a nemâzına giderse, bir haftalık günâhları afv olur ve her adımı için sevâb verilir","kisim":1,"madde":71},{"tip":"hadis","metin":"İnsanın parmakla gösterilmesi, kendisine kötülük olarak yetişir","kisim":1,"madde":71},{"tip":"hadis","metin":"Bıyıklarınızı kısaltınız! Sakalınızı uzatınız!","kisim":1,"madde":71},{"tip":"hadis","metin":"Cum’a nemâzı kılmıyanların kalblerini, Allahü teâlâ mühürler. Gâfil olurlar","kisim":1,"madde":71},{"tip":"hadis","metin":"Bir kimse, mâni’ yok iken, üç Cum’a nemâzı kılmazsa, Allahü teâlâ, kalbini mühürler. Ya’nî, iyilik yapmaz olur","kisim":1,"madde":71},{"tip":"hadis","metin":"Cum’a günlerinde bir ân vardır ki, mü’minin o ânda etdiği düâ red olmaz","kisim":1,"madde":71},{"tip":"hadis","metin":"Cum’a nemâzından sonra, yedi def’a İhlâs ve Mu’avvizeteyn okuyanı, Allahü teâlâ, bir hafta, kazâdan, belâdan ve kötü işlerden korur","kisim":1,"madde":71},{"tip":"hadis","metin":"Cum’a günü tırnağını kesen kimse, bir hafta, belâlardan emîn olur","kisim":1,"madde":71},{"tip":"hadis","metin":"Günlerin en kıymetlisi Cum’adır. Cum’a günü, bayram günlerinden ve aşûre gününden dahâ kıymetlidir. Cum’a, dünyâda ve Cennetde mü’minlerin bayramıdır","kisim":1,"madde":71},{"tip":"hadis","metin":"Cum’a günü sabâh nemâzından önce, üç kerre Estagfirullahel’azîm ellezî lâ ilâhe illâ hüvel hayyelkayyûme ve etûbü ileyh okuyanın, kendinin ve anasının ve babasının bütün günâhları afv olur","kisim":1,"madde":71},{"tip":"hadis","metin":"Cumartesi günleri yehûdîlere, pazar günleri nasârâya verildiği gibi, Cum’a günü, müslimânlara verildi. Bugün, müslimânlara hayr, bereket, iyilik vardır","kisim":1,"madde":71},{"tip":"hadis","metin":"Üzerinde farz nemâzı borcu olan kimse, kazâsını kılmadan nâfile kılarsa, boş yere zahmet çekmiş olur. Bu kimse, kazâsını ödemedikçe, Allahü teâlâ, onun nâfile nemâzlarını kabûl etmez","kisim":1,"madde":74},{"tip":"hadis","metin":"İki farz nemâzı bir araya getirmek, büyük günâhlardandır","kisim":1,"madde":74},{"tip":"hadis","metin":"Nemâz dînin direğidir. Nemâz kılan, dînini doğrultmuş olur. Nemâz kılmıyan, dînini yıkmış olur","kisim":1,"madde":74},{"tip":"hadis","metin":"Kıyâmet günü, îmândan sonra, ilk süâl nemâzdan olacakdır","kisim":1,"madde":74},{"tip":"hadis","metin":"Bir nemâzı uykuda geçiren veyâ unutan kimse, sonraki nemâzı cemâ’at ile kılarken hâtırlarsa, imâmla nemâzı bitirip, sonra önceki nemâzını kazâ etsin! Bundan sonra, imâmla kıldığını tekrâr kılsın!","kisim":1,"madde":74},{"tip":"hadis","metin":"Allahü teâlânın en çok sevdiği amel, hubb-i fillah ve buğd-ı fillahdır","kisim":1,"madde":74},{"tip":"hadis","metin":"Temâm yapılmamış olan nemâz, zekât ve başka farzlar, nâfileler ile temâmlanacakdır","kisim":1,"madde":74},{"tip":"hadis","metin":"Bir kimse, nemâzını temâmlamadı ise, o nemâzın üzerine, temâmlanıncaya kadar, nâfile nemâzları eklenir","kisim":1,"madde":74},{"tip":"hadis","metin":"Emrlerimi gücünüz yetdiği kadar yapınız. Yasak etdiklerimden sakınınız!","kisim":1,"madde":74},{"tip":"hadis","metin":"Yasak edilmiş şeyin zerresini yapmamak, bütün insanların ve cinnin ibâdetlerinden dahâ çok sevâbdır","kisim":1,"madde":74},{"tip":"hadis","metin":"Bir insanın mâ-lâ-ya’nî ile vakt geçirmesi, Allahü teâlânın, onu sevmediğinin alâmetidir","kisim":1,"madde":74},{"tip":"hadis","metin":"Büyük günâh işleyenlere şefâ’at edeceğim","kisim":1,"madde":74},{"tip":"hadis","metin":"Kıyâmetde, önce nemâzdan sorulacakdır. Nemâz doğru kılındı ise, kurtulacakdır. Nemâzı bozuk ise, işi kötü olacakdır. Farz nemâzında birşey noksan olursa, nâfileleri ile temâmlanacakdır","kisim":1,"madde":74},{"tip":"hadis","metin":"Bir nemâzı, vakti çıkdıkdan sonra kılan kimseyi, Allahü teâlâ, seksen hukbe Cehennemde bırakacakdır","kisim":1,"madde":74},{"tip":"hadis","metin":"Bir nemâzı, bilerek, özrsüz kılmıyan kimse, seksen hukbe Cehennemde kalacakdır!","kisim":1,"madde":74},{"tip":"hadis","metin":"Rükü’da ve secdelerde, belini yerine yerleşdirip biraz durmayan kimsenin nemâzını Allahü teâlâ kabûl etmez","kisim":1,"madde":77},{"tip":"hadis","metin":"Sizlerden biriniz, nemâz kılarken, rükü’dan sonra temâm kalkıp, dik durmadıkca ve ayakda, her uzv yerine yerleşip durmadıkca nemâzı temâm olmaz","kisim":1,"madde":77},{"tip":"hadis","metin":"İki secde arasında dik oturmadıkca, nemâzınız temâm olmaz","kisim":1,"madde":77},{"tip":"hadis","metin":"Eğer nemâzlarını böyle kılarak ölürsen, kıyâmet günü, sana benim ümmetimden demezler","kisim":1,"madde":77},{"tip":"hadis","metin":"Altmış sene, bütün nemâzlarını kılıp da, hiçbir nemâzı kabûl olmıyan kimse, rükü’ ve secdelerini temâm yapmıyan kimsedir","kisim":1,"madde":77},{"tip":"hadis","metin":"Unutulmuş bir sünnetimi meydâna çıkarana, yüz şehîd sevâbı verilecekdir","kisim":1,"madde":77},{"tip":"hadis","metin":"Müslimânların kabri Cennet bağçelerindendir","kisim":1,"madde":77},{"tip":"hadis","metin":"Bir yere gelen kimse E’ûzü bikelimâtillâhit-tâmmâti min şerri mâ haleka okursa, o yerden kalkıncaya kadar, ona hiçbirşey zarar, kötülük yapmaz","kisim":1,"madde":77},{"tip":"ayet","metin":"Allah, fâiz ile elde edilenleri yok eder. İzlerini bile bırakmaz. Zekâtları verilen malları artdırır","kisim":1,"madde":78},{"tip":"ayet","metin":"Allahü teâlânın ihsân etdiği malın zekâtını vermeyenler, iyi etdiklerini, zengin kalacaklarını sanıyor. Hâlbuki, kendilerine kötülük yapmış oluyorlar. O malları, Cehennemde azâb âleti olacak, yılan şeklinde boyunlarına sarılıp, başdan ayağa kadar onları sokacakdır","kisim":1,"madde":78},{"tip":"hadis","metin":"Sonra sana öderim dedi ise, istiyebilir. Öderim demedi ise, isteyemez","kisim":1,"madde":78},{"tip":"hadis","metin":"Malınızın zekâtını veriniz! Biliniz ki, zekâtını vermiyenlerin, nemâzı, orucu, haccı ve cihâdı ve îmânı yokdur","kisim":1,"madde":78},{"tip":"hadis","metin":"İlm öğrenmekde olanın kırk yıllık nafakası olsa da, buna zekât vermek câizdir","kisim":1,"madde":78},{"tip":"hadis","metin":"Allahü teâlâ, iyilik edenlere, karşılığını elbette verecekdir","kisim":1,"madde":78},{"tip":"hadis","metin":"Zekât vererek, malınızı zarardan koruyunuz!","kisim":1,"madde":78},{"tip":"hadis","metin":"Ey Âdem oğlu! Benim malım, benim malım dersin. O maldan senin olan, yiyerek yok etdiğin, giyerek eskitdiğin ve Allah için vererek, sonsuz yaşatdığındır","kisim":1,"madde":78},{"tip":"ayet","metin":"Beyâz iplik siyâhdan ayırd edilinceye kadar yiyiniz, içiniz!","kisim":1,"madde":79},{"tip":"hadis","metin":"Ayı görünce oruc tutunuz! Tekrâr görünce, orucu bırakınız!","kisim":1,"madde":79},{"tip":"hadis","metin":"Hasîslerin en kötüsü, [kesmesi vâcib olduğu hâlde] kurban kesmiyendir","kisim":1,"madde":81},{"tip":"hadis","metin":"Kurban kesecek kimse, Zilhicce ayı girince, saçını kesmesin ve tırnak kesmesin!","kisim":1,"madde":81},{"tip":"ayet","metin":"Adaklarını yerine getirsinler!","kisim":1,"madde":82},{"tip":"hadis","metin":"Tüccârın, pazarcıların çoğu fâcirdir!","kisim":1,"madde":83},{"tip":"hadis","metin":"Yalan yere yemîn ederek, birinin malını alan kimse, kıyâmet günü, Allahü teâlâyı gadablı görecekdir","kisim":1,"madde":83},{"tip":"hadis","metin":"Îmân sâhibi, her kabâhati yapabilir. Fekat, hiyânet yapamaz ve yalan söyliyemez","kisim":1,"madde":83},{"tip":"hadis","metin":"Babam hakkı için diyerek yemîn etmeyiniz! Yemîn, Allah ismi ile olur","kisim":1,"madde":83},{"tip":"hadis","metin":"Emânet, ya’nî nâmus için yemîn eden, bizden değildir","kisim":1,"madde":83},{"tip":"hadis","metin":"Kadın, yanında bir mahremi olmadan hacca gidemez!","kisim":1,"madde":84},{"tip":"hadis","metin":"Beni ziyâret için gelip, başka bir iş yapmıyarak, yalnız ziyâret edene kıyâmetde şefâ’at etmek, bende hakkı olur","kisim":1,"madde":84},{"tip":"hadis","metin":"Mescidimi Yemendeki San’â şehrine kadar genişletseler, hepsi mescidim olur","kisim":1,"madde":84},{"tip":"hadis","metin":"Farz nemâzı kılmamış olanın nâfile nemâzları kılması, vakti temâm olmuş hâmile kadına benzer. Çocuğu olacağı günlerde, çocuğu düşürür, aldırır. Çocuğu yok olduğu için, bu kadına, hâmile denemez. Ana da denemez. Bu kimse de böyledir. Farz nemâzlarını ödemedikce, Allahü teâlâ, nâfile nemâzlarını kabûl etmez","kisim":1,"madde":85},{"tip":"hadis","metin":"Tanıdığınız ve tanımadığınız müslimânlara selâm veriniz!","kisim":1,"madde":90},{"tip":"hadis","metin":"Karşılaşdığınız zemân, birbirinize eğilmeyiniz, kucaklaşmayınız!","kisim":1,"madde":90},{"tip":"hadis","metin":"Müslimânın müslimân üzerinde beş hakkı vardır: Selâmına cevâb vermek, hastasını yoklamak, cenâzesinde bulunmak, da’vetine gitmek ve aksırıp elhamdülillah diyene, yerhamükellah diyerek cevâb vermek","kisim":1,"madde":90},{"tip":"hadis","metin":"Başkalarına benzeyenler bizden değildir. Yehûdîlere ve hıristiyanlara benzemeyiniz! Yehûdîler parmakları ile işâret ederek, hıristiyanlar elleri ile işâret ederek, mecûsîler de eğilerek selâm verir","kisim":1,"madde":90},{"tip":"hadis","metin":"Yâ Ömer! Kızını, Ebû Bekrden ve Osmândan “radıyallahü anhüm” dahâ iyi birisine versem ister misin?","kisim":1,"madde":95},{"tip":"ayet","metin":"Seni, âlemlere rahmet, iyilik için gönderdik","kisim":1,"madde":96},{"tip":"hadis","metin":"Resûlullahın “sallallahü aleyhi ve sellem” hayâsı, bâkire islâm kızlarının hayâlarından dahâ çokdu","kisim":1,"madde":96},{"tip":"ayet","metin":"Sen, ya’nî Senin nûrun, hep secde edenlerden dolaşdırılıp, sana inkılâb etmiş, ulaşmışdır","kisim":1,"madde":97},{"tip":"hadis","metin":"Allahü teâlâ, İsmâ’îl “aleyhisselâm” evlâdından, Kinâne ismindeki kimseyi ve onun sülâlesinden, Kureyş ismindeki zâtı beğendi, seçdi. Kureyş evlâdından da, Hâşim oğullarını sevdi. Onlardan da, beni süzüp seçdi","kisim":1,"madde":97},{"tip":"hadis","metin":"Allahü teâlâ, insanları yaratdı. Beni insanların en iyi kısmından vücûde getirdi. Sonra, bu kısmlarından en iyisini Arabistânda yetişdirdi. Beni bunlardan vücûde getirdi. Sonra evlerden, âilelerden en iyilerini seçip, beni bunlardan meydâna getirdi. O hâlde, benim rûhum ve cesedim, mahlûkların en iyisidir. Benim silsilem, ecdâdım en iyi insanlardır","kisim":1,"madde":97},{"tip":"hadis","metin":"Allahü teâlâ, herşeyi yokdan var etdi. Herşey içinden insanları sevdi, kıymetlendirdi. İnsanlar içinden de seçdiklerini Arabistânda yerleşdirdi. Arabistândaki seçilmişler arasından da, beni seçdi. Beni, her zemândaki insanların seçilmişlerinde, en iyilerinde bulundurdu.\n\nO hâlde, Arabistânda bana bağlı olanları sevenler, benim için severler. Onlara düşmanlık edenler, bana düşmanlık etmiş olurlar","kisim":1,"madde":97},{"tip":"hadis","metin":"Benim dedelerimin hiçbiri zinâ yapmadı. Allahü teâlâ, beni, tayyib, iyi babalardan, temiz analardan getirdi. Dedelerimden birinin iki oğlu olsaydı, ben bunların en hayrlısında, en iyisinde bulunurdum","kisim":1,"madde":97},{"tip":"hadis","metin":"Ölüleri kötüliyerek, dirileri incitmeyiniz","kisim":1,"madde":97},{"tip":"hadis","metin":"Âdem aleyhisselâmdan babam Abdüllaha gelinceye kadar, hep nikâhlı ana babalardan geldim. Hiçbir babamın nikâhsız, ya’nî zinâ ile çocuğu olmadı","kisim":1,"madde":97},{"tip":"hadis","metin":"Ben sizin en iyiniz olduğum gibi, babam da, babalarınızdan dahâ iyidir","kisim":1,"madde":97},{"tip":"ayet","metin":"Allahü teâlâ, ancak takvâ sâhiblerinin [ibâdetlerini, düâlarını] kabûl eder","kisim":1,"madde":98},{"tip":"hadis","metin":"Kıyâmet günü, bol bol sevâba kavuşmak istiyen, her toplantı sonunda, Sübhâne rabbike âyetini sonuna kadar okusun!","kisim":1,"madde":98},{"tip":"hadis","metin":"Resûlullah “sallallahü aleyhi ve sellem” nemâzda, selâm vermeden evvel, Sübhâne rabbike âyet-i kerîmesini okurdu","kisim":1,"madde":98},{"tip":"hadis","metin":"Bir kimse nemâz sonunda, üç def’a Sübhâne rabbike âyet-i kerîmesini okursa, yetişir mikdârda sevâba kavuşur","kisim":1,"madde":98},{"tip":"hadis","metin":"Resûlullah “sallallahü aleyhi ve sellem” nemâzdan selâm verince, Sübhâne rabbike âyet-i kerîmesini okurdu","kisim":1,"madde":98},{"tip":"hadis","metin":"Kıyâmet günü büyük ölçeklerle, bol sevâb kazanmak istiyen kimse, bir meclisden kalkınca Sübhâne rabbike âyet-i kerîmesini okusun!","kisim":1,"madde":98},{"tip":"hadis","metin":"İnsanlara müdârâ için gönderildim","kisim":2,"madde":1},{"tip":"hadis","metin":"Yeryüzünü küfr kaplamadıkca ve her yerde küfr ve kâfirlik yapılmadıkca, hazret-i Mehdî gelmez","kisim":2,"madde":1},{"tip":"ayet","metin":"Yardım, ancak ve yalnız Allahdandır","kisim":2,"madde":2},{"tip":"hadis","metin":"Kıyâmet günü, şehîdlerin kanını, âlimlerin mürekkebi ile dartarlar. Mürekkeb ağır gelir","kisim":2,"madde":2},{"tip":"hadis","metin":"Üç dürlü baba vardır: Dünyâya getiren baba, kızını veren baba ve ilm öğreten baba. Bunların hayrlısı, üstâdıdır","kisim":2,"madde":3},{"tip":"hadis","metin":"Lâ ilâhe illallah ehline kâfir demeyiniz! Bunlara kâfir diyenin kendisi kâfir olur","kisim":2,"madde":4},{"tip":"hadis","metin":"İlm-i kelâm ile uğraşıp sapıtmak yanında, büyük günâh işlemek hafîf kalır","kisim":2,"madde":5},{"tip":"hadis","metin":"Ehl-i sünnet i’tikâdını iyi öğrenmeden önce ilm-i kelâm ile uğraşmanın zararı bilinmiş olsaydı, kelâm ilmi ile uğraşmakdan, arslandan kaçar gibi kaçınılırdı","kisim":2,"madde":5},{"tip":"hadis","metin":"Sabâh, kalkınca, üç kerre Bismillâhillezî lâ-yedurru ma’ asmihî şey’ün fil-erdı velâ fissemâi ve hüvessemî’ul’alîm okuyana akşama kadar, hiç derd, belâ gelmez","kisim":2,"madde":11},{"tip":"hadis","metin":"Birinize derd ve belâ gelince, Yûnüs Peygamberin düâsını okusun! Allahü teâlâ Onu muhakkak kurtarır. Düâ şudur: Lâ ilâhe illâ ente sübhâneke innî küntü minez-zâlimîn","kisim":2,"madde":11},{"tip":"ayet","metin":"Şeytân insana çok şeyi sözverir ve birçok şeyi hâtırlatır. Şeytânın sözverdiği şeylerin hepsi yalandır","kisim":2,"madde":13},{"tip":"ayet","metin":"Şeytânın aldatması, elbette za’îfdir","kisim":2,"madde":13},{"tip":"ayet","metin":"Şükr ederseniz, ni’metimi artdırırım!","kisim":2,"madde":14},{"tip":"hadis","metin":"Müslimân demek, müslimânlara eli ile, dili ile zarar vermiyen kimse demekdir","kisim":2,"madde":14},{"tip":"hadis","metin":"Kur’ân-ı kerîm okuyan çok kimse vardır ki, Kur’ân-ı kerîm bunlara la’net eder","kisim":2,"madde":14},{"tip":"hadis","metin":"Oruc tutan çok kimse vardır ki, onların orucu, yalnız açlık ve susuzluk çekmek olur","kisim":2,"madde":14},{"tip":"hadis","metin":"Îmânı kâmil olanınız, ahlâkı güzel olanınızdır!","kisim":2,"madde":14},{"tip":"ayet","metin":"Muhâcirînin ve Ensârın önce olanları ve bunlara tâbi’ olanlar, Allahü teâlâdan râzıdır. Allahü teâlâ da onlardan râzıdır. Onlara Cennetleri hâzırladım. Burada sonsuz kalacaklardır","kisim":2,"madde":16},{"tip":"hadis","metin":"İmâm-ı Muhammedden öğrendiklerimle, bir hayvan yükü kitâb yazdım. O olmasaydı, ilmden birşey edinemiyecekdim. İlmde, herkes, Irâk âlimlerinin çocuklarıdır. Irâk âlimleri de, Kûfe âlimlerinin talebesidir. Kûfe âlimleri ise, Ebû Hanîfenin talebesidir","kisim":2,"madde":16},{"tip":"hadis","metin":"Kâfirlere karşı malınızla, cânınızla ve dilinizle cihâd ediniz!","kisim":2,"madde":16},{"tip":"hadis","metin":"Ok atmasını ve ata binmesini öğreniniz!","kisim":2,"madde":16},{"tip":"hadis","metin":"Ok atmasını öğrenip, sonra unutan bizden değildir","kisim":2,"madde":16},{"tip":"hadis","metin":"Oyunun fâidesi olmaz. Yalnız, ok atmağı öğrenmek ve atını terbiye etmek ve âilesi ile oynamak hakdır","kisim":2,"madde":16},{"tip":"hadis","metin":"Kur’ân-ı kerîmi üç günden önce hatm eden, ma’nâsını anlayamaz","kisim":2,"madde":16},{"tip":"hadis","metin":"Âdem ve bütün Peygamberler “aleyhimüsselâm”, benimle öğündüğü gibi, ben de, ümmetim içinde, soy adı Ebû Hanîfe, ismi Nu’mân olan bir kimse ile öğünürüm ki, ümmetimin ışığı olacakdır. Onları, yoldan çıkmakdan, cehâlet karanlığına düşmekden koruyacakdır","kisim":2,"madde":16},{"tip":"hadis","metin":"Ümmetimden, Ebû Hanîfe adında biri gelecekdir. Bu, kıyâmet günü, ümmetimin ışığı olacakdır","kisim":2,"madde":16},{"tip":"hadis","metin":"Nu’mân bin Sâbit adında ve Ebû Hanîfe denilen biri gelecek, Allahü teâlânın dînini ve benim sünnetimi canlandıracakdır","kisim":2,"madde":16},{"tip":"hadis","metin":"Îmân süreyyâ yıldızına çıksa, Fâris oğullarından biri, elbette alıp getirir","kisim":2,"madde":16},{"tip":"hadis","metin":"İnsanların en hayrlısı, benim asrımda bulunan müslimânlardır. Ya’nî Eshâb-ı kirâmdır. Onlardan sonra en iyileri, onlardan sonra gelenlerdir. Ya’nî Tâbi’îndir. Onlardan sonra da en iyileri, onlardan sonra gelenlerdir. Onlardan sonra gelenlerde, yalan yayılır. Bunların sözlerine ve işlerine inanmayınız!","kisim":2,"madde":16},{"tip":"hadis","metin":"Kıyâmete yakın ilm azalır, cehâlet artar","kisim":2,"madde":16},{"tip":"ayet","metin":"Ey îmân edenler! Allahın dînine sarılınız. Birbirinizden ayrılmayınız!","kisim":2,"madde":17},{"tip":"ayet","metin":"Allahü teâlâya yaklaşmak için, vesîle arayınız!","kisim":2,"madde":17},{"tip":"hadis","metin":"Günâh işlememiş bir dil ile düâ ediniz ki, kabûl olsun!","kisim":2,"madde":17},{"tip":"hadis","metin":"Arabistânın şark tarafından bir kimseler çıkar. Kur’ân-ı kerîmi okurlar. Fekat, Kur’ân-ı kerîm, bunların buğazlarından aşağıya gitmez. Ok yaydan çıkar gibi islâmiyyetden çıkarlar. Yüzleri de hep traşlıdır","kisim":2,"madde":17},{"tip":"hadis","metin":"Hanefî mezhebinde en mükemmel ve en kıymetli fıkh kitâbı, İbni Âbidînin (Dürr-ül-muhtâr hâşiyesi","kisim":2,"madde":17},{"tip":"hadis","metin":"Allahü teâlâ, kulum farzları yapmakla bana yaklaşdığı gibi başka şeyle yaklaşamaz. Kulum nâfile ibâdetleri yapınca, onu çok severim. Öyle olur ki, benimle işitir. Benimle görür. Benimle herşeyi tutar. Benimle yürür. Benden her ne isterse veririm. Bana sığınınca, onu korurum buyurdu","kisim":2,"madde":17},{"tip":"hadis","metin":"Müslimân ismini taşıyanlardan en çok korkduğum kimse, Kur’ân-ı kerîmin ma’nâsını, yerinden değişdirenlerdir","kisim":2,"madde":17},{"tip":"hadis","metin":"Çölde yalnız kalan kimse, birşey gayb ederse, ey Allahın kulları, bana yardım ediniz desin! Çünki, Allahü teâlânın, sizin göremediğiniz kulları vardır","kisim":2,"madde":17},{"tip":"hadis","metin":"Öldükden sonra da, hayâtda olduğum gibi bilirim","kisim":2,"madde":17},{"tip":"hadis","metin":"Korkulu olan yerde, üç kerre: Ey Allahın kulları! Bana yardım ediniz demeli","kisim":2,"madde":17},{"tip":"hadis","metin":"Birşeyden zarar gören, abdest alıp iki rek’at nemâz kılsın! Sonra; Yâ Rabbî! Senden istiyorum. Senin âlemlere rahmet olan Peygamberin Muhammed aleyhisselâmı vesîle kılarak sana yalvarıyorum. Yâ Muhammed! Dileğimi kabûl etmesi için Rabbime seni vesîle ediyorum. Yâ Rabbî! Onu bana şefâ’atcı et desin","kisim":2,"madde":17},{"tip":"hadis","metin":"Âlimler, Peygamberlerin vârisleridir","kisim":2,"madde":17},{"tip":"hadis","metin":"Ümmetim yetmişüç fırkaya ayrılacak, bunlardan yalnız biri Cennete gidecekdir. Bunlar, benim ve Eshâbımın yolunda olanlardır","kisim":2,"madde":17},{"tip":"hadis","metin":"Her asr, önceki asrdan dahâ bozuk olur. Böylece kıyâmete kadar hep bozulur","kisim":2,"madde":17},{"tip":"hadis","metin":"Bid’at sâhibine hurmet eden kimse, islâmiyyeti yıkmağa yardım etmiş olur","kisim":2,"madde":17},{"tip":"hadis","metin":"Fitne veyâ bid’at yayıldığı ve Eshâbım kötülendiği zemânda, hakkı bilen, bilgisini müslimânlara duyursun! Hakkı, ya’nî doğru yolu bildiği hâlde, müslimânlara duyurmayanlara, Allahü teâlâ ve melekler ve bütün insanlar la’net eylesin! Allahü teâlâ, bu kimsenin farzlarını ve nâfile ibâdetlerini kabûl etmez","kisim":2,"madde":17},{"tip":"ayet","metin":"Sen öleceksin. O kâfirler de ölecekler. Sonra, kıyâmet günü, Rabbinizin huzûrunda hesâblaşacaksınız. Senin haklı olduğun, müşriklerin, bâtıl, bozuk olduğu meydâna çıkacak","kisim":2,"madde":18},{"tip":"ayet","metin":"Sen ölüye işitdiremezsin. Sen kabrde olana duyurucu değilsin!","kisim":2,"madde":18},{"tip":"ayet","metin":"Ölülere sen işitdiremezsin. Senin sesini, Allahü teâlâ işitdirir","kisim":2,"madde":18},{"tip":"ayet","metin":"Kâfirlere atdığını sen atmadın, onları Allahü teâlâ atdı","kisim":2,"madde":18},{"tip":"ayet","metin":"Ey insan! Sana gelen her iyilik, Allahü teâlânın ihsânı olarak, ni’meti olarak gelmekdedir. Her derd ve belâ da, kötülüklerine karşılık olarak gelmekdedir. Hepsini yaratan, gönderen Allahü teâlâdır","kisim":2,"madde":18},{"tip":"hadis","metin":"Ümmetimden, Ehl-i beytimi sevenlere şefâ’at edeceğim","kisim":2,"madde":18},{"tip":"hadis","metin":"Ümmetimden, büyük günâh işliyenlere şefâ’at edeceğim","kisim":2,"madde":18},{"tip":"hadis","metin":"Eshâbıma dil uzatanlardan başka, herkese şefâ’at edebilirim","kisim":2,"madde":18},{"tip":"hadis","metin":"Ümmetimden, nefsine zulm edenlere, nefslerine aldananlara şefâ’at edeceğim","kisim":2,"madde":18},{"tip":"hadis","metin":"Ümmetimden, günâhları çok olanlara şefâ’at edeceğim","kisim":2,"madde":18},{"tip":"hadis","metin":"Kıyâmet günü, mezârdan önce çıkan ben olacağım ve en önce şefâ’at eden ben olacağım","kisim":2,"madde":18},{"tip":"hadis","metin":"Kıyâmet günü, en önce ben şefâ’at edeceğim","kisim":2,"madde":18},{"tip":"hadis","metin":"Şefâ’atime inanmıyan, ona kavuşamaz","kisim":2,"madde":18},{"tip":"hadis","metin":"Kabrimi ziyâret eden kimseye şefâ’at etmek bana vâcib oldu","kisim":2,"madde":18},{"tip":"hadis","metin":"Kabrimi ziyâret edenin şefâ’atcisiyim","kisim":2,"madde":18},{"tip":"hadis","metin":"Kabristâna giren kimse, Yasîn sûresini okusa, o gün meyyitlerin azâbları hafîfler. Meyyitlerin sayısı kadar, ona da sevâb verilir","kisim":2,"madde":18},{"tip":"hadis","metin":"Allahü teâlânın, bir kulunu sevmemesinin alâmeti, onun mâ-lâ-ya’nî ile vakt geçirmesidir","kisim":2,"madde":19},{"tip":"ayet","metin":"Biz, Peygamber göndererek bildirmeden önce, azâb yapıcı değiliz","kisim":2,"madde":20},{"tip":"ayet","metin":"Peygamberleri, müjde vermek için ve korkutmak için gönderdim. Böylece, insanların Allahü teâlâya özr, behâne yapmaları önlendi","kisim":2,"madde":20},{"tip":"ayet","metin":"İyi biliniz ki, kalbler, Allahü teâlânın zikri ile itmînâna, râhata kavuşur!","kisim":2,"madde":20},{"tip":"hadis","metin":"Bir müctehid, âyet-i kerîmeden ve hadîs-i şerîfden [amele âid] bir hükm çıkarırken, isâbet ederse, buna on sevâb verilir. Hatâ ederse, bir sevâb verilir","kisim":2,"madde":21},{"tip":"ayet","metin":"O, boşuna konuşmaz. Hep, vahy olunanı söylemekdedir","kisim":2,"madde":23},{"tip":"ayet","metin":"Allahü teâlânın gönderdiğine uymıyanlar kâfirdir","kisim":2,"madde":23},{"tip":"ayet","metin":"Ey Peygamberim “aleyhisselâm”! Sana, Allah ve mü’minlerden, senin izinde gidenler yetişir!","kisim":2,"madde":23},{"tip":"ayet","metin":"Onlara izn verdiğin için olan hatânı, Allahü teâlâ afv etdi","kisim":2,"madde":23},{"tip":"ayet","metin":"Ey akl sâhibleri, başkalarından ibret alınız!","kisim":2,"madde":23},{"tip":"ayet","metin":"İşlerinde Eshâbın ile meşveret et, onlara danış!","kisim":2,"madde":23},{"tip":"ayet","metin":"Önce îmâna gelenlerden, her fazîletde öne geçenlerden, hem Mekkeden gelen Muhâcirlerden, hem de Medînede bunları karşılayıp yardım eden Ensârdan, önde olanlardan ve iyilikde bunların izinde gidenlerden Allahü teâlâ râzıdır.\n\nHepsini sever. Onlar da, Allahü teâlâdan râzıdır. Allahü teâlâ, Onlara Cenneti hâzırladı. Cennetde sonsuz kalacaklardır","kisim":2,"madde":23},{"tip":"ayet","metin":"Mekke şehri alınmadan önce, din düşmanları ile harb edenler ve mallarını, Allah yolunda harc edenler ile, Mekke alındıkdan sonra, bunları yapanlar, müsâvî, eşit değildir. Birinciler elbette dahâ yüksekdir. Allahü teâlâ, hepsine Hüsnâyı, ya’nî Cenneti söz verdi","kisim":2,"madde":23},{"tip":"ayet","metin":"Ağaç altında, sana söz veren mü’minlerden, Allahü teâlâ elbette râzıdır","kisim":2,"madde":23},{"tip":"ayet","metin":"Onlar, birbirine, her zemân ve çok iyilik edicidir","kisim":2,"madde":23},{"tip":"hadis","metin":"İslâmiyyet değirmeni, otuzbeş sene veyâhud otuzyedi sene devâm edecekdir","kisim":2,"madde":23},{"tip":"hadis","metin":"Bir kimse, şeytâna la’net ederse, ben zâten mel’ûn oldum. Bu la’netin bana zararı olmaz der. Yâ Rabbî! Beni şeytândan koru derse, eyvâh bel kemiğimi kırdın der","kisim":2,"madde":24},{"tip":"hadis","metin":"Şeytâna söğmeyiniz! Şerrinden, Allahü teâlâya sığınınız","kisim":2,"madde":24},{"tip":"ayet","metin":"Mekke-i mükerremenin fethinden önce malını veren ve cihâd eden kimseye, fethden sonra malını dağıtan ve cihâd edenden dahâ büyük derece vardır. Allahü teâlâ, hepsine Cenneti va’d etdi","kisim":2,"madde":25},{"tip":"ayet","metin":"Ey Peygamberim “sallallahü aleyhi ve sellem”! Sana yardımcı olarak Allahü teâlâ ve mü’minlerden sana tâbi’ olanlar yetişir","kisim":2,"madde":25},{"tip":"ayet","metin":"Size gelen belâlar, kabâhatlerinizin cezâsıdır","kisim":2,"madde":25},{"tip":"ayet","metin":"Âdeme önce söyledik. Fekat unutdu. Azm ile, karâr ile yapmadı","kisim":2,"madde":25},{"tip":"ayet","metin":"Allahü teâlâ, onlara zulm etmez. Onlar, kendi kendilerine zulm edip, ağır cezâları hak etdiler","kisim":2,"madde":25},{"tip":"ayet","metin":"Kâfirler: Bu nasıl Peygamberdir? “sallallahü aleyhi ve sellem”. Bizim gibi yiyip içiyor, sokaklarda geziyor. Peygamber olsaydı, kendisine melek gelirdi. Yardımcıları olur, bize onlar da haber verir, Cehennem ile korkuturlardı. Yâhud, Rabbi, para hazîneleri gönderir, yâhud, meyve bağçeleri, çiftlikleri olur, istediğini yirdi dediler...","kisim":2,"madde":25},{"tip":"hadis","metin":"İşçiye, alnının teri kurumadan hakkını veriniz","kisim":2,"madde":26},{"tip":"ayet","metin":"Allahü teâlâ kullarını, selâmet, se’âdet yeri olan Cennetine da’vet ediyor. Dilediğini bu yola kavuşdurur","kisim":2,"madde":28},{"tip":"ayet","metin":"Nefslerine uyanlardan, doğru yolu arayanları, se’âdete ulaşdıran yollara kavuşdururuz","kisim":2,"madde":28},{"tip":"ayet","metin":"Ey cin ve ey insan! Gücünüz yeterse, yer yüzünden ve semâlardan dışarı çıkınız. Çıkmanız için, çok kuvvet ister. O kuvvet de sizde yokdur","kisim":2,"madde":31},{"tip":"hadis","metin":"Mehr vermemek niyyeti ile nikâh yapan kimse, kıyâmet günü hırsızlar arasında haşr olunacakdır","kisim":2,"madde":34},{"tip":"hadis","metin":"Bunların çocukları za’îf, hastalıklı olur","kisim":2,"madde":34},{"tip":"hadis","metin":"Kadın, yâ malı için veyâ güzelliği için, yâhud dîni için alınır. Siz dîni olanı alınız! Malı için alan, malına kavuşamaz. Yalnız cemâl için alan, cemâlinden mahrûm kalır","kisim":2,"madde":34},{"tip":"hadis","metin":"Ev satın almadan evvel, komşuların nasıl olduklarını araşdırınız! Yola çıkmadan evvel, yol arkadaşınızı seçiniz!","kisim":2,"madde":38},{"tip":"hadis","metin":"Komşuya hurmet etmek, anaya hurmet etmek gibi lâzımdır","kisim":2,"madde":38},{"tip":"hadis","metin":"Komşusu, şerrinden emîn olmıyan kimse, Allahü teâlâya îmân etmemişdir","kisim":2,"madde":38},{"tip":"hadis","metin":"Zimmî komşunun bir hakkı, müslimân komşunun iki hakkı, akrabâ olan komşunun üç hakkı vardır","kisim":2,"madde":38},{"tip":"hadis","metin":"Evinizde pişen yemekden, komşunuzun hakkını veriniz!","kisim":2,"madde":38},{"tip":"hadis","metin":"Sıkıntıya düşen komşusuna yardım eden, sıkıntısını gideren kimseye, Allahü teâlâ kıyâmet günü kıymetli elbise giydirecekdir","kisim":2,"madde":38},{"tip":"hadis","metin":"Allahü teâlâ, bir sâlih müslimânın hurmetine, komşularından binlerce belâyı, felâketi uzaklaşdırır","kisim":2,"madde":38},{"tip":"hadis","metin":"Kendisinin iyi mi, kötü mü olduğunu anlamak istiyen kimse, sâlih, hâlis olan komşularının kendisi hakkında ne dediklerini öğrensin! İyi kimsedir diyorlarsa, ind-i ilâhîde iyi olduğunu anlasın!","kisim":2,"madde":38},{"tip":"ayet","metin":"Müslimân kadınlar, zînetlerini göstermesinler! İş yaparken zarûrî açılanlar günâh olmaz. Baş örtülerini yakalarına kadar örtsünler [Böylece, saçları, kulakları ve göğüsleri iyi örtülsün]","kisim":2,"madde":39},{"tip":"hadis","metin":"Müslimânların en iyisi, en fâidelisi, zevcesine karşı iyi ve fâideli olandır","kisim":2,"madde":39},{"tip":"hadis","metin":"Bir kimse, kızını fâsıka [kötü kimseye] verirse, Allahü teâlânın emânetine hıyânet etmiş olur. Emânete hıyânet edenlerin gideceği yer, Cehennemdir","kisim":2,"madde":39},{"tip":"hadis","metin":"Kızını fâsıka veren kimse, mel’ûndur","kisim":2,"madde":39},{"tip":"hadis","metin":"Dört şeyi yapan, ya’nî kocasına hıyânet etmiyen, beş vakt nemâz kılan, Ramezân-ı şerîfde oruc tutan ve [onsekiz erkekden] başkasına, [başı, saçı, kolları, bacakları] açık olarak görünmiyen kadın Cennete gidecekdir","kisim":2,"madde":39},{"tip":"hadis","metin":"Beş şeyi yapan kadın Cehennemden kurtulur: Beş vakt nemâzını kılar, Ramezân ayında orucunu tutar, zevcini, anasını babasını üzmez, yüzünü ve saçlarını yabancı erkeklere göstermez, dünyâ sıkıntılarına sabr eder","kisim":2,"madde":39},{"tip":"hadis","metin":"Her dürlü lehv harâmdır. Yalnız, zevce ile oynamak, at ve silâh ile ta’lîm, yarış yapmak câizdir","kisim":2,"madde":39},{"tip":"hadis","metin":"Kadının neresine olursa olsun, şehvet ile bakan kimsenin gözlerine kıyâmet günü erimiş kurşun dökülecek, sonra Cehenneme atılacakdır","kisim":2,"madde":39},{"tip":"hadis","metin":"Yabancı genc kadının elini tutan kimsenin eline kıyâmet günü ateş doldurulacakdır","kisim":2,"madde":39},{"tip":"hadis","metin":"Şefâ’atime kavuşmak istiyen, kızını fâsıka vermesin!","kisim":2,"madde":39},{"tip":"hadis","metin":"Yâ Alî! Üç şeyi gecikdirme! Nemâzı evvel vaktinde kıl! Hâzırlanmış cenâzenin nemâzını hemen kıl! Dul veyâ kızı küfvü isteyince, hemen evlendir!","kisim":2,"madde":39},{"tip":"hadis","metin":"Bir erkek, zevcesini döğerse, kıyâmetde ben onun da’vâcısı olurum","kisim":2,"madde":39},{"tip":"ayet","metin":"Ey Peygamberlerim “salevâtullahi aleyhim ecma’în”. Halâl ve temiz yiyiniz ve bana lâyık ibâdetler yapınız!","kisim":2,"madde":40},{"tip":"ayet","metin":"Allahı çok zikr eden erkeklerin ve kadınların günâhları afv olur ve çok sevâb verilir","kisim":2,"madde":40},{"tip":"hadis","metin":"Halâl kazanmak her müslimâna farzdır","kisim":2,"madde":40},{"tip":"hadis","metin":"Bir kimse, hiç harâm karışdırmadan, kırk gün halâl yirse, Allahü teâlâ, onun kalbini nûr ile doldurur. Kalbine, nehrler gibi hikmet akıtır. Dünyâ muhabbetini, kalbinden giderir","kisim":2,"madde":40},{"tip":"hadis","metin":"Harâm yiyenlerin ne farzları, ne de sünnetleri kabûl olmaz","kisim":2,"madde":40},{"tip":"hadis","metin":"On liralık elbisenin, bir lirası harâm olsa, o elbise ile kılınan nemâzlar kabûl olmaz","kisim":2,"madde":40},{"tip":"hadis","metin":"Harâm ile beslenen vücûdün ateşde yanması dahâ iyidir","kisim":2,"madde":40},{"tip":"hadis","metin":"Malın halâlden mi, harâmdan mı geldiğini düşünmiyenler, Cehenneme, neresinden atılırsa atılsınlar, Allahü teâlâ, onlara acımıyacakdır","kisim":2,"madde":40},{"tip":"hadis","metin":"İbâdet on kısmdır, dokuz kısmı, halâl kazanmakdır","kisim":2,"madde":40},{"tip":"hadis","metin":"Halâl kazanmak için yorulup, evine dönen kimse, günâhsız olarak yatar. Allahü teâlânın sevdiği kimse olarak kalkar","kisim":2,"madde":40},{"tip":"hadis","metin":"Allahü teâlâ buyuruyor ki, harâmdan kaçınanlara hesâb sormağa utanırım","kisim":2,"madde":40},{"tip":"hadis","metin":"Bir dirhem fâiz [almak ve vermek], otuz zinâdan dahâ günâhdır","kisim":2,"madde":40},{"tip":"hadis","metin":"Harâm maldan verilen sadaka kabûl edilmez. Saklanırsa, Cehenneme gidinceye kadar, ona yolluk olur","kisim":2,"madde":40},{"tip":"hadis","metin":"Kanbur oluncıya kadar nemâz kılsanız ve kıl gibi oluncıya kadar oruc tutsanız, harâmdan kaçınmadıkca, kabûl edilmez, fâidesi olmaz","kisim":2,"madde":40},{"tip":"hadis","metin":"Bir müslimân, tehlükeli olan şeyin korkusundan dolayı, tehlükesiz şeyden sakınmadıkca, müttekî olamaz!","kisim":2,"madde":40},{"tip":"hadis","metin":"Bizler harâma düşmek korkusu ile, halâllerin onda dokuzundan kaçındık","kisim":2,"madde":40},{"tip":"hadis","metin":"İnsanların en kötüsü, köşkler, çeşidli yemekler, renkli elbiseler içinde, boş oturup, herkese hoş gelen, lüzûmsuz sözlerle vakt geçirenlerdir","kisim":2,"madde":40},{"tip":"hadis","metin":"İstemeden verilen şeyi alınız! Allahü teâlânın gönderdiği rızkdır","kisim":2,"madde":40},{"tip":"hadis","metin":"Çok kimse vardır ki, yidikleri ve giydikleri harâmdır. Sonra ellerini kaldırıp düâ ederler. Böyle düâ, nasıl kabûl olunur?","kisim":2,"madde":40},{"tip":"hadis","metin":"Her yıl, kendinden önceki yıldan dahâ kötü olacakdır","kisim":2,"madde":40},{"tip":"hadis","metin":"Allaha ve Âhıret gününe inanan kimse, şerâb içilen sofraya oturmasın!","kisim":2,"madde":40},{"tip":"hadis","metin":"Kâr haddi koymayınız! Fiyât koyan, Allahü teâlâdır","kisim":2,"madde":40},{"tip":"hadis","metin":"Resûlullah “sallallahü aleyhi ve sellem” yüzüğünü sağ eline takardı","kisim":2,"madde":41},{"tip":"hadis","metin":"Ey Allahın kulları! Hasta olunca, tedâvî etdiriniz! Çünki Allahü teâlâ, hastalık gönderince, ilâcını da gönderir","kisim":2,"madde":41},{"tip":"ayet","metin":"Yüz mü’min, ikiyüz kâfire gâlip gelir","kisim":2,"madde":42},{"tip":"hadis","metin":"Şerâb içen kimse, tevbesiz ölürse, mezârını açınız! Yüzünü kıbleye karşı görürseniz, beni öldürünüz!","kisim":2,"madde":42},{"tip":"hadis","metin":"Suyu, alkollü içki içenler gibi içmek harâmdır","kisim":2,"madde":42},{"tip":"hadis","metin":"Çok içildiği zemân serhoş eden şeyin, az içilmesi de harâmdır","kisim":2,"madde":42},{"tip":"hadis","metin":"Şerâb içen ile arkadaşlık etmeyiniz! Cenâzesine gitmeyiniz! Buna kız vermeyiniz ve onun kızı ile evlenmeyiniz! Muhakkak biliniz ki, şerâb içen, kıyâmet günü, mezârdan yüzü kara, gözleri mâvi olarak kalkar. Dili sarkmış, pis kokulu olur. Herkes, bunun pis kokusundan kaçar","kisim":2,"madde":42},{"tip":"hadis","metin":"Şerâb içmeği âdet eden, vesene tapan gibidir","kisim":2,"madde":42},{"tip":"hadis","metin":"Bir yudum şerâb içene, Allahü teâlâ üç gün gadab eder","kisim":2,"madde":42},{"tip":"hadis","metin":"Şerâbda devâ, ilâc hâssası yokdur. Hastalık yapar","kisim":2,"madde":42},{"tip":"hadis","metin":"Şerâb içmek, büyük günâhların en büyüğüdür. Bütün kötülüklerin anasıdır, başıdır. Şerâb içen, nemâz kılmaz. Anası ile, halası ile, teyzesi ile zinâ eder","kisim":2,"madde":42},{"tip":"hadis","metin":"Gece nemâz kılanların yüzü güzel olur","kisim":2,"madde":42},{"tip":"hadis","metin":"Şübheli şeyleri yapan, harâm da işler","kisim":2,"madde":43},{"tip":"hadis","metin":"Soğan, sarmısak yiyen, mescidimize gelmesin!","kisim":2,"madde":43},{"tip":"hadis","metin":"Söylemediğim birşeyi hadîs diyerek yalan söyliyen, Cehennemde ateşden kazık üzerine oturtulacakdır","kisim":2,"madde":43},{"tip":"ayet","metin":"Tebzîr etme! Tebzîr edenler, şeytânların kardeşleridir","kisim":2,"madde":44},{"tip":"ayet","metin":"Mallarınızı sefîhlere, alçaklara vermeyiniz!","kisim":2,"madde":44},{"tip":"ayet","metin":"Fâiz yiyenler, kıyâmet günü mezârlarından, sar’a hastası gibi perişân kalkacaklardır","kisim":2,"madde":44},{"tip":"ayet","metin":"Allahü teâlâ, fâiz alan ve verenlerin mallarının hepsini yok eder. İzini, eserini de bırakmaz. Zekât verenlerin malını elbette artdırır","kisim":2,"madde":44},{"tip":"ayet","metin":"Şükr ederseniz, verdiğim ni’metleri elbette artdırırım","kisim":2,"madde":44},{"tip":"ayet","metin":"Ekini hasâd etdiğiniz zemân, fakîrlerin haklarını verin ve isrâf etmeyin. Allahü teâlâ, isrâf edenleri elbette sevmez","kisim":2,"madde":44},{"tip":"ayet","metin":"Ey Habîbim! Malını, kendine kalmıyacak şeklde dağıtma!","kisim":2,"madde":44},{"tip":"hadis","metin":"Kıyâmet günü herkes, dört süâle cevâb vermedikce hesâbdan kurtulamıyacakdır: Ömrünü nasıl geçirdi. İlmi ile nasıl amel etdi. Malını nereden, nasıl kazandı ve nerelere harc etdi. Cismini, bedenini nerede yordu, hırpaladı?","kisim":2,"madde":44},{"tip":"hadis","metin":"İyi niyyet ile mal kazanmak, mal kazanmamakdan iyidir","kisim":2,"madde":44},{"tip":"hadis","metin":"Allahü teâlâ, bir kuluna mal ve ilm verir. Bu kul da harâmlardan kaçınır. Akrabâsını sevindirir. Malından, hakkı olanları bilip verir ise, Cennetin yüksek derecesine gider","kisim":2,"madde":44},{"tip":"hadis","metin":"Malı ve evlâdı çok olmak istiyen bitkisel yemek çok yisin!","kisim":2,"madde":45},{"tip":"hadis","metin":"Üç şey ahmaklıkdır: Diş ile tırnak uçlarını yimek, sakal yolmak ve balçık yimek","kisim":2,"madde":45},{"tip":"hadis","metin":"İyiliklerin başı açlıkdır. Kötülüklerin başı toklukdur","kisim":2,"madde":45},{"tip":"hadis","metin":"Sağ el ile yiyiniz. Sağ el ile içiniz","kisim":2,"madde":45},{"tip":"hadis","metin":"Çok yiyeni, çok içeni Allahü teâlâ sevmez","kisim":2,"madde":45},{"tip":"hadis","metin":"Günâhı çok olan, çok su dağıtsın!","kisim":2,"madde":45},{"tip":"hadis","metin":"Allahü teâlâ, kuluna derd vermek isterse, sakalını yolmağı ve tırnağını ısırmağı âdet eder","kisim":2,"madde":45},{"tip":"hadis","metin":"Üç şey, bedeni besler: Güzel koku, yumuşak kumaşdan güzel elbise ve bal yimek","kisim":2,"madde":45},{"tip":"hadis","metin":"İnsan kalbi, tarladaki ekin gibidir. Yemek, yağmur gibidir. Fazla su, ekini kurutduğu gibi, fazla gıdâ kalbi öldürür","kisim":2,"madde":45},{"tip":"hadis","metin":"Ümmetim hulbenin fâidesini bilse, ağırlığı kadar altın verip, satın alırdı","kisim":2,"madde":46},{"tip":"ayet","metin":"İlm-i yakîn ile bilseydiniz, Cehennemi elbette görürdünüz","kisim":2,"madde":47},{"tip":"ayet","metin":"Hepinizin dünyâya getirilmesi ve âhıretde tekrâr diriltilmesi, bir kişinin yaratılması ve diriltilmesi gibidir","kisim":2,"madde":47},{"tip":"ayet","metin":"Onların âhıretdeki hâlleri, dünyâdaki hâlleri gibidir","kisim":2,"madde":47},{"tip":"ayet","metin":"Herşeye kuvvet veren, ancak Allahü teâlâdır","kisim":2,"madde":47},{"tip":"ayet","metin":"Şeytân, muhtâc hâle düşeceğinizi, size söz veriyor","kisim":2,"madde":47},{"tip":"hadis","metin":"Bir kimse geceyi, yarın yapacağı işleri düşünmekle geçirir. Hâlbuki o iş, bu kimsenin felâketine sebeb olacakdır. Allahü teâlâ, bu kuluna acıyıp, o işi yapdırmaz. O ise, iş olmadığı için, üzülür. Bu işim neden olmıyor. Kim yapdırmıyor. Bana kim düşmanlık ediyor diye arkadaşlarına kötü gözle bakmağa başlar. Hâlbuki, Allahü teâlâ, ona merhamet ederek felâketden korumuşdur","kisim":2,"madde":47},{"tip":"hadis","metin":"Sen tevekkül etmek için, benim âdetimi, hikmetimi değişdirmek istiyorsun. İlâclara, fâideli te’sîrleri kim verdi? Elbette ben yaratıyorum","kisim":2,"madde":47},{"tip":"hadis","metin":"Hasta olup, musîbete, felâkete uğrayıp da, günâhları afv olacağı için sevinmiyen kimse, âlim değildir","kisim":2,"madde":47},{"tip":"hadis","metin":"Allahü teâlâ buyurdu ki: Hastalık benim kemendim, tuzağımdır ve fakîrlik zındânımdır. Buralara sevdiklerimi sokarım","kisim":2,"madde":47},{"tip":"hadis","metin":"Allahü teâlâdan âfiyet isteyiniz. Belâ istemeyiniz!","kisim":2,"madde":47},{"tip":"hadis","metin":"Allahü teâlâya tam tevekkül etseydiniz, kuşların rızkını verdiği gibi, size de gönderirdi. Kuşlar, sabâh mi’deleri boş, aç gider. Akşam mi’deleri dolmuş, doymuş olarak döner","kisim":2,"madde":47},{"tip":"hadis","metin":"Bir kimse, Allahü teâlâya sığınırsa, Allahü teâlâ, onun her işine yetişir. Hiç ummadığı yerden, ona rızk verir. Her kim, dünyâya güvenirse, onu dünyâda bırakır","kisim":2,"madde":47},{"tip":"hadis","metin":"Gadab, ya’nî asabiyyet, Cehennem ateşinden bir parçadır","kisim":2,"madde":47},{"tip":"hadis","metin":"Bütün Meleklerden işitdim ki, ümmetine söyle, hacâmat yapdırsınlar. Ya’nî kan aldırsınlar dediler","kisim":2,"madde":47},{"tip":"hadis","metin":"Arabî ayın onyedinci veyâ ondokuzuncu veyâ yirmibirinci günleri hacâmat olunuz ki, kan artarsa [ya’nî tansiyon yükselirse], ölüme sebeb olur","kisim":2,"madde":47},{"tip":"hadis","metin":"Allahü teâlânın ölüme sebeb yapdığı hastalıklardan birisi, kanın artmasıdır","kisim":2,"madde":47},{"tip":"hadis","metin":"Allahü teâlâ, harâm olan şeylerde, size şifâ yaratmamışdır","kisim":2,"madde":47},{"tip":"hadis","metin":"Bir kimse, âilesi ile buluşdukda, azl eylemez ise, ya’nî çocuk olmasına mâni’ olmazsa, çocuk olsa da olmasa da, bu kimseye, şehîd oluncıya kadar cihâd eden bir yeğid sevâbı verilir","kisim":2,"madde":47},{"tip":"hadis","metin":"İnsan, kendine zulm edene beddüâ eder. Böylece, hakkını, dünyâda almış olur. Belki, zâlimin hakkı da, kendine geçmiş olur","kisim":2,"madde":47},{"tip":"hadis","metin":"Mûsâ “aleyhisselâm”, Yâ Rabbî! Hastalığı yapan kimdir, hastalığı iyi eden kimdir, dedi. Cenâb-ı Hak, her ikisini de yapan benim, buyurdu. O hâlde, tabîbe ne lüzûm var deyince, onlar, şifâ için yaratdığım sebebleri bilir ve kullarıma verir. Ben de onlara, bu yoldan rızk ve sevâb veririm, buyurdu","kisim":2,"madde":47},{"tip":"hadis","metin":"Şübhe edilen altını, ateşle mu’âyene etdikleri gibi, Allahü teâlâ, insanları derd ile, belâ ile imtihân eder. Ba’zısı, belâ ateşinden hâlis olarak çıkar. Ba’zısı da, bozuk olarak çıkar","kisim":2,"madde":47},{"tip":"hadis","metin":"Sıtma hastalığı, insanın günâhlarının hepsini temizler. Dolu dânesinde toz olmadığı gibi, sıtmalının günâhı kalmaz","kisim":2,"madde":47},{"tip":"hadis","metin":"Mü’minlerde, üç şeyden biri bulunur: Kıllet ya’nî fakîrlik, ıllet ya’nî hastalık, zillet, ya’nî i’tibârsızlık","kisim":2,"madde":47},{"tip":"ayet","metin":"Ecel, bir ân gecikmez ve vaktinden önce gelmez","kisim":2,"madde":48},{"tip":"ayet","metin":"Herkesin ömrü ve ömürlerin kısalması hep yazılıdır","kisim":2,"madde":48},{"tip":"hadis","metin":"Kazâ-i mu’allak, Levh-i mahfûzda yazılıdır. Eğer o kimse, iyi amel yapıp, düâsı kabûl olursa, o kazâ değişir","kisim":2,"madde":48},{"tip":"hadis","metin":"Kazâ-i mu’allakı, hiçbirşey değişdiremez. Yalnız düâ değişdirir ve ömrü, yalnız, ihsân, iyilik artdırır","kisim":2,"madde":48},{"tip":"hadis","metin":"Kader, tedbîr ile, sakınmakla değişmez. Fekat kabûl olan düâ, o belâ gelirken korur","kisim":2,"madde":48},{"tip":"ayet","metin":"İnsanları ve cinnîleri ancak, Beni bilip, itâ’at, ibâdet etmeleri için yaratdım!","kisim":2,"madde":49},{"tip":"ayet","metin":"Allahü teâlânın indinde din, islâm dînidir","kisim":2,"madde":49},{"tip":"hadis","metin":"İrâde-i cüz’iyye, bir varlık değildir. Var olmıyan şey, yaratılmış olmaz. İrâde-i cüz’iyye, kullarda bir hâldir. Kuvveti, birşeyi yapmak ve yapmamakda kullanmakdır. Kullar, irâde-i cüz’iyyelerini kullanmakda serbestdir. Mecbûr değildir","kisim":2,"madde":49},{"tip":"hadis","metin":"Bir kimse, bütün ömrünce Cehennem ateşine götürecek günâhlar yapar. Bu kimse, ömrünün son günlerinde, Cennete götürecek iyilikler yaparak, Cennete gider","kisim":2,"madde":50},{"tip":"ayet","metin":"Ba’zı şeyleri sever, fâideli dersiniz. Hâlbuki o şeyler size zararlıdır","kisim":2,"madde":52},{"tip":"ayet","metin":"Beğendiğiniz, sevdiğiniz çok şey vardır ki, sizin için zararlıdır!","kisim":2,"madde":52},{"tip":"hadis","metin":"Sizden sonra, bir zemân gelecekdir. O zemânda bulunan müslimânların en sefîlleri, en aşağıları, müezzinlerdir","kisim":2,"madde":52},{"tip":"hadis","metin":"Hâkimler rüşvet alarak haksız karâr verir. Adam öldürmek çoğalır. Gençler, ana babalarını, hısm akrabâsını aramaz, saymaz olur. Kur’ân-ı kerîm mizmârdan, ya’nî çalgı âletlerinden okunur. Tecvîd ile, güzel okuyanları, islâmiyyete uyan hâfızları dinlemeyip, mûsikî ile şarkı gibi okuyanları dinlerler.","kisim":2,"madde":52},{"tip":"hadis","metin":"Ümmetimdeki münâfıkların çoğu, Kur’ân-ı kerîm okuyanlardan olacakdır","kisim":2,"madde":52},{"tip":"hadis","metin":"Nikâhı herkese duyurunuz! Bunun için de, câmi’lerde yapınız ve defler çalınız!","kisim":2,"madde":52},{"tip":"hadis","metin":"Bir zemân gelir ki, müslimânlar birbirlerinden ayrılır, parçalanırlar. İslâmiyyeti bırakıp, kendi düşüncelerine, görüşlerine uyarlar. Kur’ân-ı kerîmi mizmârlardan, ya’nî çalgılardan, şarkı gibi okurlar. Allah için değil, keyf için okurlar.\n\nBöyle okuyanlara ve dinleyenlere hiç sevâb verilmez. Allahü teâlâ bunlara la’net eder. Azâb verir!","kisim":2,"madde":52},{"tip":"hadis","metin":"Mizmârları kırmak için ve hınzırları öldürmek için gönderildim","kisim":2,"madde":52},{"tip":"hadis","metin":"Kur’ân-ı kerîmi arab şîvesi ile, onların sesi ile okuyunuz! Fâsıklar, şarkıcılar gibi okumayınız!","kisim":2,"madde":52},{"tip":"hadis","metin":"Kur’ân-ı kerîm, okuyanlarına, yâ şefâ’at edecek veyâ düşman olacakdır","kisim":2,"madde":52},{"tip":"hadis","metin":"Kur’ân-ı kerîm okuyan çok kimse vardır ki, Kur’ân-ı kerîm, onlara la’net eder","kisim":2,"madde":52},{"tip":"hadis","metin":"Şi’r, iyisi iyi olan, çirkini çirkin olan sözdür","kisim":2,"madde":52},{"tip":"ayet","metin":"İnsanları ve Cinnîleri ancak, beni bilip itâ’at, ibâdet etmeleri için yaratdım","kisim":2,"madde":53},{"tip":"hadis","metin":"O mektûbu kaldır. Yoksa, mektûbun acısını, kıyâmete kadar çekerler!","kisim":2,"madde":53},{"tip":"hadis","metin":"Yatarken Âyet-el kürsî okuyana, şeytân yaklaşamaz","kisim":2,"madde":53},{"tip":"ayet","metin":"Ey Rabbimiz, bizimle kavmimiz arasında sen hak olanı hükm et. Sen hükm edenlerin hayrlısısın!","kisim":2,"madde":55},{"tip":"ayet","metin":"Ey Peygamberim! Allahü teâlâ ve senin yolunda olan mü’minler, sana kâfîdirler!","kisim":2,"madde":57},{"tip":"ayet","metin":"İnsan, ihtiyâcsız olunca, elbette azar!","kisim":2,"madde":57},{"tip":"hadis","metin":"Karşıki ağaca git, de ki, Allahın Peygamberi seni çağırıyor!","kisim":2,"madde":61},{"tip":"ayet","metin":"Kullarım senden beni soruyorlar. Ben onlara çok yakınım!","kisim":2,"madde":62},{"tip":"ayet","metin":"Üç adam gizli konuşunca, Allah onların dördüncüsü olur. Beş kişi gizli konuşunca, Allah onların altıncısı olur. Dahâ az veyâ dahâ çok kimseler olunca da, her nerede olursa olsunlar, Allah onlarla berâberdir","kisim":2,"madde":62},{"tip":"ayet","metin":"Her fırkada bulunanlar, kendi anladıklarını doğru sanırlar","kisim":2,"madde":62},{"tip":"ayet","metin":"Onu gözler anlıyamaz. O ise, gözleri bilir, anlar. O, ihsân sâhibi bilicidir","kisim":2,"madde":67},{"tip":"ayet","metin":"Peygamber göndermedikce azâb yapmayız!","kisim":2,"madde":67},{"tip":"ayet","metin":"Biz, Peygamber göndermedikçe, azâb yapıcı değiliz","kisim":2,"madde":67},{"tip":"hadis","metin":"Nemâz kılarken, Allahü teâlâyı görmek mümkin değil ise de, görür gibi bir hâl hâsıl olmakdadır","kisim":2,"madde":72},{"tip":"hadis","metin":"Yâ Bilâl “radıyallahü teâlâ anh”! Beni râhatlandır!","kisim":2,"madde":72},{"tip":"hadis","metin":"Îsâ aleyhisselâmın yapdığını yapmakda ben herkesden ilerideyim. Peygamberler “aleyhimüsselâm”, babaları bir olan kardeşler gibidirler. Anaları ayrıdır. Dinleri birdir","kisim":2,"madde":72},{"tip":"ayet","metin":"Allahü teâlâ, bu üstünlüğü dilediğine ihsân eder","kisim":2,"madde":73},{"tip":"hadis","metin":"Küfrü açık bilinmiyen kimseye kâfir diyen, kâfir olur","kisim":2,"madde":73},{"tip":"hadis","metin":"Kolay şeyleri yapınız! İşlerinizi güçleşdirmeyiniz! Gücünüz yetdiği şeyleri yapınız! Allahü teâlâ, kolay olanları yapmanızı istiyor","kisim":2,"madde":73},{"tip":"hadis","metin":"Geceleri, Rabbimin ziyâfetindeyim. Beni doyuruyor ve içiriyor","kisim":2,"madde":73},{"tip":"hadis","metin":"Bir zemân gelecek. Elbisenin rengi, zîneti solduğu gibi, yer yüzünde islâmiyyet de solup kalkacak. Öyle olacak ki, nemâz, oruc, hac, sadaka unutulacak. Kur’ân-ı kerîmden yer yüzünde bir âyet kalmıyacak","kisim":3,"madde":1},{"tip":"hadis","metin":"Bid’at işliyenlere büyük diyen, müslimânlığı yıkmağa yardım etmiş olur","kisim":3,"madde":1},{"tip":"ayet","metin":"Onlara, kâfirlere inanmayınız dediğim hâlde, onlar kâfirlerin sözleri ile hareket ediyorlar. Şeytân onları aldatıyor","kisim":3,"madde":2},{"tip":"ayet","metin":"Biz, Allahü teâlânın varlığına, birliğine, herşeyi yaratan O olduğuna inandık, müslimân olduk diyenlerin çoğu, başkalarına ibâdet ve itâ’at ederek ve dahâ birçok hareketleri ve sözleri ile, müşrik oluyorlar","kisim":3,"madde":2},{"tip":"ayet","metin":"Mü’minlere söyle, yabancı kadınlara bakmasınlar ve zinâ etmesinler! Ve mü’min kadınlara söyle! Onlar da, yabancı erkeklere bakmasınlar ve zinâ etmesinler!","kisim":3,"madde":2},{"tip":"hadis","metin":"İlâcların en iyisi Kur’ân-ı kerîmdir","kisim":3,"madde":2},{"tip":"hadis","metin":"Yabancı kadınlara bakmak, gözlerin zinâsıdır. Onları tutmak, ellerin zinâsıdır. Onlara gitmek, ayakların zinâsıdır","kisim":3,"madde":2},{"tip":"hadis","metin":"Müslimân sihr yapamaz. Allah saklasın îmânı gitdikden sonra, sihri te’sîr eder.","kisim":3,"madde":2},{"tip":"hadis","metin":"Uzak yoldan gelmiş, saçı sakalı dağılmış, yüzü gözü toz içinde bir kimse, ellerini göke doğru uzatıp düâ ediyor. “Yâ Rabbî!” diye yalvarıyor. Hâlbuki yidiği harâm, içdiği harâm, gıdâsı hep harâm. Bunun düâsı nasıl kabûl olur?","kisim":3,"madde":3},{"tip":"hadis","metin":"Bu kimse câhildir. İslâmiyyetden haberi yokdur. Çünki, Resûlullah “sallallahü aleyhi ve sellem” buyurdu ki, (Allahü teâlâ benim rızkımı, süngümün ucuna koymuşdur","kisim":3,"madde":3},{"tip":"hadis","metin":"Elinin emeği, alnının teri ile yi, dînini satıp yime!","kisim":3,"madde":3},{"tip":"hadis","metin":"Halâle, harâma dikkat ederek çalışıp kazanan kimseyi, Allahü teâlâ çok sever","kisim":3,"madde":3},{"tip":"hadis","metin":"Bir dirhem gümüş kıymetinde harâm alan kimseyi, yirmibeşbin sene Cehennemde bırakacaklardır","kisim":3,"madde":3},{"tip":"hadis","metin":"Bir müslimân, halâl kazanıp, kimseye muhtâc olmaz ve komşularına, akrabâsına yardım ederse, kıyâmet günü, ayın ondördü gibi parlak, nûrlu olacakdır","kisim":3,"madde":3},{"tip":"hadis","metin":"Doğru olan tüccâr, kıyâmetde sıddîklarla ve şehîdlerle berâber olacakdır","kisim":3,"madde":3},{"tip":"hadis","metin":"Allahü teâlâ, san’at sâhibi mü’mini sever","kisim":3,"madde":3},{"tip":"hadis","metin":"En halâl şey, san’at sâhibinin kazandığıdır","kisim":3,"madde":3},{"tip":"hadis","metin":"Ticâret yapınız! Rızkın onda dokuzu ticâretdedir","kisim":3,"madde":3},{"tip":"hadis","metin":"Kendini başkasından sadaka istiyecek hâle düşüreni, Allahü teâlâ yetmiş şeye muhtâc eder","kisim":3,"madde":3},{"tip":"hadis","metin":"Beş vakt nemâzı kıldıkdan sonra, çalışıp halâl kazanmak, her müslimâna farzdır","kisim":3,"madde":3},{"tip":"hadis","metin":"İnsanların iyisi, insanlara fâidesi olanlardır","kisim":3,"madde":3},{"tip":"hadis","metin":"Eshâbım için fakîrlik se’âdetdir. Âhır zemândaki ümmetim için, zenginlik se’âdetdir","kisim":3,"madde":3},{"tip":"hadis","metin":"Bir zemân gelecek ki, insanlar, yalnız malın, paranın gelmesini düşünüp, halâlini, harâmını düşünmiyecekler","kisim":3,"madde":3},{"tip":"hadis","metin":"Halâl kazanmak için sıkıntı çekenlere Cennet vâcib olur","kisim":3,"madde":3},{"tip":"hadis","metin":"Iyne satışı yaparsanız ve cihâdı terkedip, zirâ’at ile uğraşırsanız, Allahü teâlâ sizi zelîl eder. Dîninize dönmedikce, bu zilletden kurtulamazsınız!","kisim":3,"madde":12},{"tip":"ayet","metin":"Verirken noksân, alırken fazla ölçenlere acı azâblar yapacağım","kisim":3,"madde":15},{"tip":"hadis","metin":"Bir kimse gıdâ maddelerini alıp, pahâlı olup da satmak için kırk gün saklarsa, hepsini fakîrlere parasız dağıtsa, günâhını ödiyemez","kisim":3,"madde":15},{"tip":"hadis","metin":"Bir kimse gıdâ maddelerini kırk gün saklarsa, Allahü teâlâ ona darılır. O, Allahü teâlâyı saymamış olur","kisim":3,"madde":15},{"tip":"hadis","metin":"Biz, az kâr ile çok sevâb kazanmağı dahâ çok severiz. Fazla kazanmak için, dînimizi fedâ etmemeli idin. Çok büyük cinâyet yapmışsın. Bunu afv etdirmek için sermâyeyi ve kârı hemen sadaka olarak dağıt!","kisim":3,"madde":15},{"tip":"hadis","metin":"Köylü, tarlasından aldığı gıdâ maddelerini istediği zemân satabilir. Acele satması vâcib değildir. Fekat, acele etmesi sevâbdır. Pahâlı olunca satmasını düşünmesi çirkindir. İlâclarda ve gıdâ maddesi olmıyan ve herkese lâzım olmıyan şeylerde ihtikâr harâm değildir. Ekmek ve benzerlerinde çok harâm olup, et, yağ gibilerde az harâmdır","kisim":3,"madde":15},{"tip":"hadis","metin":"Ticârete hıyânet karışınca, bereket gider","kisim":3,"madde":15},{"tip":"hadis","metin":"Lâ ilâhe illallah diyenler, dünyâyı dinden üstün tutmadıkca, Allahü teâlânın gadabından, azâbından kurtulurlar. Dîni bırakıp, dünyâya sarılırlarsa, bu kelime-i tevhîdi söyleyince, Allahü teâlâ, onlara, yalan söylüyorsun! buyurur","kisim":3,"madde":15},{"tip":"hadis","metin":"Bir kimse, hâricden gıdâ maddesi satın alıp, şehre getirir ve piyasaya göre satarsa, sadaka vermiş gibi sevâb kazanır veyâ köle âzâd etmiş gibi sevâb kazanır","kisim":3,"madde":15},{"tip":"hadis","metin":"Alış-verişde vallahi böyledir, vallahi öyle değildir diye yemîn edenlere ve san’at sâhiblerinden, yarın gel, öbür gün gel diye sözünde durmıyanlara yazıklar olsun!","kisim":3,"madde":15},{"tip":"hadis","metin":"Malını yemîn ederek beğendiren kimseye kıyâmet günü merhamet edilmiyecek, acınmıyacakdır","kisim":3,"madde":15},{"tip":"ayet","metin":"İhsân edenlere, elbette rahmetim çok yakındır","kisim":3,"madde":16},{"tip":"hadis","metin":"Alış-verişde kolaylık gösterenlere, Allahü teâlâ, her işinde kolaylık gösterir","kisim":3,"madde":16},{"tip":"hadis","metin":"Kıyâmetde bir kimseyi hesâba çekerler ki, çok günâh işlemiş, hiç iyilik yapmamış. Sen dünyâda hiç iyilik yapmadın mı? derler. Hayır, yalnız çırağıma derdim ki, (Fakîr olan borcluları sıkışdırma! Ne zemân ellerine geçerse, o zemân vermelerini söyle. İstediklerini yine ver. Boş çevirme!","kisim":3,"madde":16},{"tip":"hadis","metin":"Sadaka verilen her dirhem için on sevâb, ödünc verilen her dirhem için ise, onsekiz sevâb vardır. Çünki, borc, ihtiyâcı olana verilir. Sadaka belki, ihtiyâcı olmayanın eline düşebilir","kisim":3,"madde":16},{"tip":"hadis","metin":"En iyiniz, borcunu iyi ödiyeninizdir","kisim":3,"madde":16},{"tip":"hadis","metin":"Ödünc alan bir kimse, iyice ödemeği niyyet ederse, borcunu ödemesi için, melekler ona düâ eder","kisim":3,"madde":16},{"tip":"ayet","metin":"Mallarınız ve çocuklarınız, Allahü teâlâyı, hâtırlamanıza mâni’ olmasın!","kisim":3,"madde":17},{"tip":"hadis","metin":"Ey tüccârlar! Önce âhıret rızkını kazanın! Sonra dünyâ rızkına çalışın!","kisim":3,"madde":17},{"tip":"hadis","metin":"Gündüz ve gece melekleri, sabâh ve akşam, gidip gelirken birbirleri ile karşılaşırlar. Hak teâlâ, [giden meleklere], kullarımı nasıl bırakdınız? buyurur. Yâ Rabbî! Nemâzda bulduk ve nemâz kılarken bırakdık, derler. Allahü teâlâ da, şâhid olun, onları afv etdim buyurur","kisim":3,"madde":17},{"tip":"hadis","metin":"Gâfiller arasında Allahü teâlâyı zikr eden kimse, kurumuş ağaçlar arasında bulunan yeşil fidân gibidir ve ölüler arasındaki cânlı gibidir ve harbde kaçanlar arasında, arslan gibi döğüşenler gibidir","kisim":3,"madde":17},{"tip":"hadis","metin":"Çarşıya giderken, lâ ilâhe illallah, vahde hü lâ şerîke leh, le hül mülkü ve le hül hamdü, yuhyî ve yümît, ve hüve hayyün lâ yemût, bi yedi-hil-hayr, ve hüve alâ külli şey’in kadîr diyen kimseye, iki milyon sevâb yazılır","kisim":3,"madde":17},{"tip":"hadis","metin":"Pazarda çok kimse vardır ki, sôfîler halkasında oturanlardan dahâ kıymetlidir","kisim":3,"madde":17},{"tip":"hadis","metin":"Bir zemân gelir ki, o zemânın müslimânları, bugün sizin yapdığınız ibâdetlerin onda birini yaparsa, âhıretde azâbdan kurtulurlar","kisim":3,"madde":17},{"tip":"hadis","metin":"En iyi ticâret, bezzâzlıkdır, kumaş satmakdır. En iyi san’at, terzilikdir","kisim":3,"madde":17},{"tip":"hadis","metin":"Melekler insanların amel defterlerini götürdükleri zemân, başında ve sonunda iyi iş yazılı ise, gün ortasında yapılanları ona bağışlarlar","kisim":3,"madde":17},{"tip":"hadis","metin":"Tüccârın, esnâfın en kötüsü, erken gidip, geç dönenlerdir","kisim":3,"madde":17},{"tip":"hadis","metin":"Dâr-ül-harbde, müslimân ile kâfir arasında fâiz yokdur","kisim":3,"madde":19},{"tip":"hadis","metin":"Kur’ân-ı kerîm okuyunuz. Fekat, bunu geçim vâsıtası yapmayınız!","kisim":3,"madde":21},{"tip":"hadis","metin":"Ezân okuyun. Ezân için ücret almayın!","kisim":3,"madde":21},{"tip":"hadis","metin":"Serhoş eden her içki şerâb gibi harâmdır","kisim":3,"madde":22},{"tip":"hadis","metin":"Günâh işliyeni gören, eli ile mâni’ olsun. Buna gücü yetmezse, dili ile mâni’ olsun!","kisim":3,"madde":23},{"tip":"hadis","metin":"Fuhş söyliyenlerin Cennete girmeleri harâmdır","kisim":3,"madde":23},{"tip":"hadis","metin":"Hayâ, îmândandır. Fuhş söylemek, cefâdandır. Îmân Cennete, cefâ Cehenneme götürür","kisim":3,"madde":23},{"tip":"hadis","metin":"Fuhş insanın lekesi, hayâ, zînetidir","kisim":3,"madde":23},{"tip":"hadis","metin":"Kul haklarını ödeyen, her nemâzdan sonra onbir ihlâs-i şerîf okuyan ve kâtilini afv ederek ölen Cennete girecekdir","kisim":3,"madde":24},{"tip":"hadis","metin":"Ekber-i kebâir, birşeyi Allahü teâlâya ortak etmek, adam öldürmek, anaya, babaya karşı gelmek, yalancı şâhidlik yapmakdır","kisim":3,"madde":24},{"tip":"hadis","metin":"Ananın, babanın yüzüne merhamet ile bakana, makbûl hac sevâbı verilir","kisim":3,"madde":26},{"tip":"ayet","metin":"Allahü teâlâ, dilediğini seçerek kendine kavuşdurur","kisim":3,"madde":27},{"tip":"ayet","metin":"Biliniz ki kalbler, ancak Allahı zikr etmekle itmînâna kavuşur","kisim":3,"madde":27},{"tip":"ayet","metin":"Nereye dönerseniz, orada Allahü teâlâyı bulursunuz!","kisim":3,"madde":27},{"tip":"hadis","metin":"Mevlânâ Zeyn-üd-dîn-i Taybâdî “kaddesallahü teâlâ sirrehül’azîz” ilm ile Allahü teâlâya vâsıl olmuşdur","kisim":3,"madde":27},{"tip":"hadis","metin":"Zikr ederek, kalblerinin yükünü hafîfletenlerin yolunda olunuz!","kisim":3,"madde":27},{"tip":"hadis","metin":"Onlar görüldüğü vakt, Allah hâtırlanır","kisim":3,"madde":27},{"tip":"ayet","metin":"Allahü teâlâ, müşriki afv etmiyecekdir","kisim":3,"madde":28},{"tip":"ayet","metin":"Allahü teâlânın, günâhlarını iyiliklerle değişdireceği kimseler, onlardır. Allahü teâlânın magfireti, merhameti sonsuzdur","kisim":3,"madde":29},{"tip":"ayet","metin":"Bizim gibi bir insan mı bize yol gösterecek, diyerek kâfir oldular","kisim":3,"madde":30},{"tip":"ayet","metin":"Bu nasıl Peygamberdir? Bizim gibi yiyor ve sokaklarda dolaşıyor dediler","kisim":3,"madde":30},{"tip":"hadis","metin":"Zemânların en hayrlısı benim zemânımdır","kisim":3,"madde":31},{"tip":"ayet","metin":"Yer küresini iki günde yaratdı","kisim":3,"madde":33},{"tip":"ayet","metin":"Allahü teâlâ, gökleri ve yeri altı günde yaratdı ve Arşı, su üzerinde idi","kisim":3,"madde":33},{"tip":"ayet","metin":"Onun Kürsîsi, göklerden ve yerden genişdir","kisim":3,"madde":33},{"tip":"ayet","metin":"Rabbinizi, yalvararak ve gizli ve sessiz çağırınız","kisim":3,"madde":37},{"tip":"ayet","metin":"Biliniz ki, kalbler, yalnız Allahü teâlâyı zikr etmekle râhat bulur","kisim":3,"madde":37},{"tip":"hadis","metin":"Câhiliyye zemânında iyi olanlarınız, müslimân olup din bilgilerini öğrenince de, en iyiniz olur!","kisim":3,"madde":38},{"tip":"ayet","metin":"Şeytânın askeri elbette mağlûb olacak, ziyân edecekdir","kisim":3,"madde":43},{"tip":"hadis","metin":"Hâllerin doğru olmasına alâmet, bunlara tam bir yakîn ve inanmakdır","kisim":3,"madde":44},{"tip":"hadis","metin":"Her gördüğün, her işitdiğin ve her bildiğin, O değildir. Bunların hepsini, (Lâ","kisim":3,"madde":44},{"tip":"hadis","metin":"Allahü teâlâ ile kul arasında, yetmişbin nûrdan perde ve yetmişbin zulmetden perde vardır","kisim":3,"madde":44},{"tip":"ayet","metin":"Allahü teâlâ, dilediğini kendine seçer, kendine kavuşmak isteyenlere de, kavuşduran yolu gösterir","kisim":3,"madde":51},{"tip":"ayet","metin":"Belki anlamadıkları için inanmıyorlar. Onun sözünün özünü anlamadılar. Bunlardan önce olanlar da, böyle inanmamışlardı","kisim":3,"madde":51},{"tip":"hadis","metin":"İnsan nemâza başlayınca, Allahü teâlâ ile kul arasında olan perde kalkar","kisim":3,"madde":51},{"tip":"hadis","metin":"Siz dünyâ işlerinizi dahâ iyi bilirsiniz!","kisim":3,"madde":52},{"tip":"hadis","metin":"Âhıretde azâb görmez,\n dünyâ işlerinde, bana tâbi’ olan","kisim":3,"madde":53},{"tip":"hadis","metin":"Lezzetleri yıkan, eğlencelere son veren ölümü çok hâtırlayınız!","kisim":3,"madde":55},{"tip":"hadis","metin":"Sizler, ancak ebediyyet, sonsuzluk için yaratıldınız! Lâkin bir evden, bir eve göç edersiniz!","kisim":3,"madde":55},{"tip":"hadis","metin":"Ölüm hastası yanında, bir sûre okununca, her harfi için bir melek gelip, rûhun kolay çıkmasına düâ eder. Yıkanırken yanında bulunurlar. Cenâzesi ile birlikde giderler. Nemâzında bulunurlar. Gömülürken bulunurlar. Hep düâ ederler","kisim":3,"madde":55},{"tip":"hadis","metin":"Allahü teâlâdan iyilik umarak cân veriniz!","kisim":3,"madde":55},{"tip":"hadis","metin":"Allahü teâlâyı unutarak, gafletle edilen düâ kabûl olmaz","kisim":3,"madde":55},{"tip":"hadis","metin":"Allahü teâlânın bir ni’met vermesini ve bunun devâmlı olmasını isteyen, Lâ havle velâ kuvvete illâ billah çok okusun!","kisim":3,"madde":55},{"tip":"hadis","metin":"Bu, Cennet hazînelerinden bir hazînedir!","kisim":3,"madde":55},{"tip":"hadis","metin":"İnsanlar uykudadır, ölünce uyanırlar","kisim":3,"madde":55},{"tip":"hadis","metin":"Yanında Yasîn-i şerîf okunan hasta, suya doymuş olarak vefât eder ve doymuş olarak kabre girer","kisim":3,"madde":55},{"tip":"hadis","metin":"Müslimân bir hasta yanında Yasîn-i şerîf okunursa, Rıdvân ismindeki melek Cennet şerbeti getirir. Suya doymuş olarak rûh teslîm eder. Doymuş olarak kabre girer. Suya ihtiyâcı olmaz.","kisim":3,"madde":55},{"tip":"hadis","metin":"Bir kimse, Allahü teâlâya kavuşmağı severse, Allahü teâlâ da ona kavuşmağı sever","kisim":3,"madde":55},{"tip":"hadis","metin":"Hastalığınızı tedâvî ediniz! Çünki, Allahü teâlâ, ölümden başka her hastalık için, devâ, ilâc yaratmışdır","kisim":3,"madde":55},{"tip":"hadis","metin":"Âdem “aleyhisselâm” vefât edince, melekler Cennetden hanût ve kefen getirdiler. Su ve sedr yaprağı ile yıkadılar. Üçüncüsünde kâfûr koydular. Üç kefen ile kefenlediler. Nemâzını kıldılar. Lahd yapdılar. Defn etdiler. Sonra çocuklarına dönerek, ey Âdem oğulları! Ölülerinize böyle yapınız dediler","kisim":3,"madde":56},{"tip":"hadis","metin":"Cenâzeyi yüksek sesle ve ateş, ışık ve başka şeyler taşıyarak götürmeyiniz!","kisim":3,"madde":58},{"tip":"hadis","metin":"Bir hasta, lâ ilâhe illâ ente sübhâneke innî küntü minezzâlimîn kırk def’a okursa, şehîd olarak vefât eder. Şifâ bulursa, günâhları afv olur","kisim":3,"madde":58},{"tip":"hadis","metin":"Kabristâna girince, Fâtiha, Kul-e’ûzüler ve İhlâs sûrelerini okuyunuz! Sevâbını meyyitlere gönderiniz! Sevâbı hepsine vâsıl olur.","kisim":3,"madde":59},{"tip":"hadis","metin":"Nemâzda ayakda iken okunan Kur’ânın her harfi için yüz sevâb verilir. Nemâz dışında abdestli okuyunca, her harfi için yirmibeş sevâb verilir. Abdestsiz okuyunca, on sevâb verilir. Yürürken ve iş yaparken okuyunca, dahâ az sevâb verilir.","kisim":3,"madde":59},{"tip":"hadis","metin":"Kur’ân okunan eve, bereket, iyilik gelir. Melekler oraya toplanır. Şeytânlar oradan kaçar","kisim":3,"madde":59},{"tip":"hadis","metin":"Bir kimse, gündüz hatm okursa, melekler ona akşama kadar düâ eder. Gece okunursa, sabâha kadar düâ ederler","kisim":3,"madde":59},{"tip":"hadis","metin":"Ana-babasının veyâ ikisinden birinin kabrini her Cum’a günleri ziyâret edenin günâhları afv olur. Haklarını ödemiş olur","kisim":3,"madde":59},{"tip":"hadis","metin":"Ümmetimin yapdığı ibâdetlerin en kıymetlisi, Kur’ân-ı kerîmi, Mushafa bakarak okumakdır","kisim":3,"madde":59},{"tip":"hadis","metin":"Nemâzda okunan Kur’ân, nemâz dışında okunan Kur’ândan dahâ hayrlıdır","kisim":3,"madde":59},{"tip":"hadis","metin":"İnsanın dinlediği bir âyet, kıyâmetde kendine nûr olur","kisim":3,"madde":59},{"tip":"hadis","metin":"Kur’ân-ı kerîm okuyunca, Allahü teâlânın rızâsını ve Cenneti isteyiniz! Dünyâlık istemeyiniz! Bir zemân gelir ki, hâfızlar, Kur’ân-ı kerîmi, insanlara yaklaşmak için vâsıta yaparlar","kisim":3,"madde":59},{"tip":"hadis","metin":"İnsanların en iyisi, hatmi bitirince, yeniden başlıyandır","kisim":3,"madde":59},{"tip":"hadis","metin":"Kur’ân-ı kerîm okuyanın ana-babası kâfir olsalar bile, azâbları hafîfler","kisim":3,"madde":59},{"tip":"hadis","metin":"Kur’ân-ı kerîmi hatm edenin düâsı kabûl olunur","kisim":3,"madde":59},{"tip":"hadis","metin":"İbâdetlerin en iyisi, hatm okuyup, bitince yenisine başlamakdır","kisim":3,"madde":59},{"tip":"hadis","metin":"Kur’ân-ı kerîmi tecvîde uygun okuyana şehîd sevâbı verilir","kisim":3,"madde":59},{"tip":"hadis","metin":"Üç mescidden başka mescidlere ziyâret için gidilmez","kisim":3,"madde":59},{"tip":"hadis","metin":"Bir mü’minin kabrini ziyâret ederken, Allahümme innî es’elüke-bi-hurmet-i Muhammed aleyhisselâm en lâ tü’azzibe hâzelmeyyit derse, o meyyitin azâbı kıyâmete kadar ref’ olur","kisim":3,"madde":59},{"tip":"hadis","metin":"Bir kimse, tanıdığının kabri yanından geçerken selâm verirse, meyyit bunu tanır ve selâmına cevâb verir","kisim":3,"madde":59},{"tip":"hadis","metin":"Bir kimse, kabristândan geçerken, onbir kerre İhlâs sûresi okuyup sevâbını meyyitlere hediyye ederse, kendisine ölüler adedince sevâb verilir","kisim":3,"madde":59},{"tip":"hadis","metin":"Kur’ân-ı kerîmi tecvîd bilgisine uyarak okuyunca, her harfine yirmi sevâb verilir. Tecvîde uymazsa, on sevâb verilir","kisim":3,"madde":59},{"tip":"hadis","metin":"Ben ölünce üzülmeyiniz! Her yerde benimle olunuz, beni düşününüz! İmdâdınıza yetişir, size yardım ederim. Rûhumun, bu dünyâda iki dürlü bağlılığı vardır: Biri, bedenime olan bağlılığı, ikincisi, sizlere olan bağlılığı. Allahü teâlânın inâyeti ile, ferd ve mücerred olunca, ya’nî rûhum bedenden ayrılınca, bedene olan bağlılığı da, size olur.","kisim":3,"madde":60},{"tip":"hadis","metin":"Bir mü’min, tanıdığı bir mü’minin kabrine gelip selâm verince, onu tanır ve cevâb verir","kisim":3,"madde":60},{"tip":"hadis","metin":"Bir kimse, kendisi için veyâ başkası için yetmişbin aded Kelime-i tevhîd okursa, günâhları afv olur","kisim":3,"madde":62},{"tip":"hadis","metin":"Resûlullah “sallallahü aleyhi ve sellem” odama geldi. Çömlekde et kaynıyordu. Ekmek ile evde bulunan birşey ikrâm etdim. (Et pişdiğini gördüm","kisim":3,"madde":63},{"tip":"hadis","metin":"Bir kimse, başkası yerine oruc tutamaz ve nemâz kılamaz. Fekat, onun orucu ve nemâzı için fakîri doyurur","kisim":3,"madde":63},{"tip":"hadis","metin":"Ferâiz ilmini öğrenmeğe çalışınız! Bu ilmi gençlere öğretiniz! Ferâiz ilmi, din bilgisinin yarısı demekdir. Ümmetimin en önce unutacağı, bırakacağı şey, bu ilm olacakdır","kisim":3,"madde":64},{"tip":"hadis","metin":"Tâ’ûn, eski ümmetlere, azâb olarak gönderildi. Bu ümmet için şehîd olmağa sebebdir","kisim":3,"madde":67},{"tip":"hadis","metin":"Bir kimse, mü’minler için, hergün yirmibeş kerre, istigfâr okursa, Allahü teâlâ, bu kimsenin kalbinden gıl ve hasedi çıkarır. İsmi, Ebdâl ismleri arasına yazılır. Ona, bütün mü’minler adedince, sevâb yazılır. Kıyâmet günü, bütün mü’minler: Yâ Rabbî, bu kulun bizim için, istigfâr okurdu. Sen de onu afv eyle! derler","kisim":3,"madde":69},{"tip":"ayet","metin":"Bilen ile bilmiyen hiç bir olur mu? Bilen elbette kıymetlidir","kisim":3,"madde":70},{"tip":"ayet","metin":"Ey mü’minler! Dâimâ, her zemân, sâdıklar ile birlikde bulunun!","kisim":3,"madde":70},{"tip":"hadis","metin":"İyi huyları temâmlamak, iyi ahlâkı dünyâya yaymak için gönderildim","kisim":3,"madde":70},{"tip":"hadis","metin":"Allah adamlarının kalbleri, Hakkın nazargâhıdır. O kalblere girmiş olanlara da, o nazardan nasîb erişir.","kisim":3,"madde":70},{"tip":"hadis","metin":"Ebû Cehl ve Ebû Leheb gibi ahmaklar, Allahü teâlânın sevgili Peygamberini “sallallahü aleyhi ve sellem” görmediler. Ebû Tâlibin yetîmi, Abdüllahın oğlu Muhammedi “sallallahü aleyhi ve sellem” gördüler. O gözle bakdılar. Eğer, Ebû Bekr-i Sıddîk gibi bakarak, Resûlullah olarak görselerdi, eşkıyâlıkdan, küfrden kurtulur, Onun gibi kemâle gelirlerdi","kisim":3,"madde":70},{"tip":"hadis","metin":"Bilerek yapılan az bir ibâdet, bilmiyerek yapılan çok ibâdetden dahâ iyidir!","kisim":3,"madde":70},{"tip":"hadis","metin":"Îmânı yüksek olanınız, ahlâkı güzel olanınızdır!","kisim":3,"madde":70},{"tip":"hadis","metin":"Allahü teâlânın, kalbime akıtdığı, doldurduğu feyzlerin, nûrların hepsini Ebû Bekrin kalbine akıtdım!","kisim":3,"madde":70},{"tip":"hadis","metin":"Vera’ sâhibi ile birlikde oturmak ibâdetdir","kisim":3,"madde":70},{"tip":"hadis","metin":"Kur’ân-ı kerîmi kendi anladığına göre tefsîr eden kâfir olur","kisim":3,"madde":70}];
